  detail_payload = '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"busan-small-group-sightseeing-tour-cruise-passengers","locale":"es","product_id":"busan-small-group-sightseeing-tour-cruise-passengers","seo":{"pageTitle":"Excursión en tierra desde el crucero de Busan: Tour en grupo pequeño de día | AtoC Korea","metaDescription":"Excursión en tierra de 8 horas en furgoneta compartida desde la terminal de cruceros de Busan: Memorial de la ONU, acantilados de Taejongdae, Pueblo Cultural de Gamcheon, Parque Yongdusan, Mercado de Jagalchi.","primaryKeywords":["Tour de día en crucero por Busan","Visita turística en grupo pequeño por Busan","Tour por el Pueblo Cultural de Gamcheon","Tour en crucero por Taejongdae","Tour por el Mercado de Jagalchi"],"ogImage":"https://www.atockorea.com/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp"},"catalog_card":{"thumbnail":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","title":"Busan Crucero: Grupo Pequeño","priceLabel":"","shortCardDescription":"Tour de día en furgoneta compartida desde la terminal de cruceros de Busan que incluye las cinco paradas más solicitadas de la ciudad en una ventana de 8 horas: Cementerio Memorial de la ONU (contexto de la Guerra de Corea), acantilados costeros de Taejongdae, almuerzo en un restaurante local de Busan, Pueblo Cultural de Gamcheon (la ladera pintada), Parque Yongdusan con observatorio opcional en la Torre de Busan, y Mercado de Jagalchi. Recogida coordinada con el desembarco específico de su barco. Guía certificado con habla inglesa y china.","tags":["small_group","busan","cruise_excursion","from_cruise","shared_van"],"rating":0,"reviewCount":0,"slug":"busan-small-group-sightseeing-tour-cruise-passengers","subtitle":"Cinco lugares emblemáticos de Busan desde su terminal de cruceros en un día de 8 horas en furgoneta compartida.","region":"Busan","duration":"8 horas","stopsCount":9,"badges":["Excursión en crucero","Furgoneta compartida pequeña","Recogida en el puerto","Ventana de 8 horas"],"heroImage":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp"},"headlineLine1":"Busan Crucero","headlineLine2":"Grupo Pequeño","price":{"amountLabel":"68.95","currency":"USD","per":"person","salePriceUsd":68.95},"hero":{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","imagePosition":"center 35%","tagline":"Cinco lugares emblemáticos de Busan coordinados con el horario de su barco, en una furgoneta compartida con otros cruceristas","pills":["small_group","crucero","busan"],"meta":{"duration":"≈ 8 horas, coordinadas con la escala en puerto de su crucero","region":"Busan","stops":"9 paradas","rating":0,"ratingStars":5}},"subnavItems":[{"id":"overview","label":"Descripción general"},{"id":"itinerary","label":"Itinerario"},{"id":"details","label":"Detalles"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"Reseñas"}],"glanceItems":[{"icon":"camera","label":"Valor fotográfico","value":"Excelente","level":5},{"icon":"mountain","label":"Pintoresco","value":"Bueno","level":4},{"icon":"footprints","label":"A pie","value":"Alto","level":4},{"icon":"cloud-rain","label":"Seguridad bajo la lluvia","value":"Moderado","level":3},{"icon":"users","label":"Apto para familias","value":"Moderado","level":3},{"icon":"gauge","label":"Equilibrio","value":"Equilibrado","level":4}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Cementerio Memorial de la ONU (Guerra de Corea)","alt":"Cementerio Memorial de la ONU (Guerra de Corea) — gallery image 1","caption":"Cementerio Memorial de la ONU (Guerra de Corea) — photo 1"},{"id":2,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"Acantilados costeros de Taejongdae","alt":"Acantilados costeros de Taejongdae — gallery image 1","caption":"Acantilados costeros de Taejongdae — photo 1"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Aldea Cultural de Gamcheon","alt":"Aldea Cultural de Gamcheon — gallery image 1","caption":"Aldea Cultural de Gamcheon — photo 1"},{"id":4,"type":"photo","src":"/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","location":"Parque Yongdusan y Torre de Busan","alt":"Parque Yongdusan y Torre de Busan — gallery image 1","caption":"Parque Yongdusan y Torre de Busan — photo 1"},{"id":5,"type":"photo","src":"/images/tours/songdo-beach/chatgpt-image-2026-5-10-12-32-12.webp","location":"Nampo-dong y Mercado de Pescado Jagalchi","alt":"Nampo-dong y Mercado de Pescado Jagalchi — on-route photo","caption":"Nampo-dong y Mercado de Pescado Jagalchi"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Cementerio Memorial de la ONU (Guerra de Corea)","alt":"Cementerio Memorial de la ONU (Guerra de Corea) — gallery image 2","caption":"Cementerio Memorial de la ONU (Guerra de Corea) — photo 2"},{"id":7,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Cementerio Memorial de la ONU (Guerra de Corea)","alt":"Cementerio Memorial de la ONU (Guerra de Corea) — gallery image 3","caption":"Cementerio Memorial de la ONU (Guerra de Corea) — photo 3"},{"id":8,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Cementerio Memorial de la ONU (Guerra de Corea)","alt":"Cementerio Memorial de la ONU (Guerra de Corea) — gallery image 4","caption":"Cementerio Memorial de la ONU (Guerra de Corea) — photo 4"},{"id":9,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Cementerio Memorial de la ONU (Guerra de Corea)","alt":"Cementerio Memorial de la ONU (Guerra de Corea) — gallery image 5","caption":"Cementerio Memorial de la ONU (Guerra de Corea) — photo 5"},{"id":10,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Cementerio Memorial de la ONU (Guerra de Corea)","alt":"Cementerio Memorial de la ONU (Guerra de Corea) — gallery image 6","caption":"Cementerio Memorial de la ONU (Guerra de Corea) — photo 6"},{"id":11,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-43.webp","location":"Acantilados costeros de Taejongdae","alt":"Acantilados costeros de Taejongdae — gallery image 2","caption":"Acantilados costeros de Taejongdae — photo 2"},{"id":12,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-47.webp","location":"Acantilados costeros de Taejongdae","alt":"Acantilados costeros de Taejongdae — gallery image 3","caption":"Acantilados costeros de Taejongdae — photo 3"},{"id":13,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Aldea Cultural de Gamcheon","alt":"Aldea Cultural de Gamcheon — gallery image 2","caption":"Aldea Cultural de Gamcheon — photo 2"},{"id":14,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Aldea Cultural de Gamcheon","alt":"Aldea Cultural de Gamcheon — gallery image 3","caption":"Aldea Cultural de Gamcheon — photo 3"},{"id":15,"type":"photo","src":"/images/tours/busan-tower/kakaotalk-20260510-222952680.webp","location":"Parque Yongdusan y Torre de Busan","alt":"Parque Yongdusan y Torre de Busan — gallery image 2","caption":"Parque Yongdusan y Torre de Busan — photo 2"},{"id":16,"type":"photo","src":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp","location":"Parque Yongdusan y Torre de Busan","alt":"Parque Yongdusan y Torre de Busan — gallery image 3","caption":"Parque Yongdusan y Torre de Busan — photo 3"}],"itineraryStops":[{"number":1,"time":"≈ 09:00","duration":"Ventana de 15 min","name":"Recogida en el Puerto de Busan (sala de llegadas de la terminal de cruceros)","category":"Salida","description":"La recogida es en **la sala de llegadas de la terminal de cruceros de Busan en la que atraque tu barco**: la Terminal Internacional de Cruceros de Busan (Yeongdo) o la Terminal Internacional de Pasajeros del Puerto de Busan (Choryang). Ninguna es la opción por defecto: depende de dónde atraque tu barco y se confirma al reservar.\n\nAl desembarcar, sigue los carteles hasta la sala de llegadas. Tu guía espera allí con un cartel de AtoC Korea y una tarjeta de itinerario impresa. Por favor, preséntate en el punto de encuentro **antes de las 08:50 para salir a las 09:00**.\n\nEl día dura unas **8 horas** y termina de vuelta en tu terminal hacia las 17:00. El guía reconfirma en la recogida el all-aboard de tu barco y ajusta el orden del día si tu salida es inusualmente temprana.","highlights":["Recogida: sala de llegadas de la **Terminal Internacional de Cruceros del Puerto de Busan** (Dongsam) o la **Terminal Internacional de Pasajeros** (Choryang)","**Furgoneta/minibús de grupo reducido (máx. ~14 pax)** — compartido con otros pasajeros de crucero","El guía lleva un cartel con el nombre ''AtoC Korea — Busan Day Tour''","**Pausa para almorzar** en un restaurante de Busán recomendado por la guía (gasto propio, ₩10,000–15,000) en restaurante local de Busan","**Embarque 30 min después del despacho del barco** (margen para inmigración)"],"whyOnRoute":"Recogerte en la sala de llegadas de la terminal elimina lo que más se tuerce en un día de escala: buscar transporte local con el reloj en marcha. El encuentro a las 09:00 deja margen tras el desembarque de la mañana y aun así mete las nueve paradas en una jornada de ocho horas, de vuelta en la terminal a las 17:00.","_poi_meta":{"poi_key":"OPS_busan_cruise_pickup","kb_version":"1.15","verified_date":"2026-04-29","sources":["Busan Port Authority","CruiseMapper"]},"image":null,"_role":"pickup"},{"name":"Templo Haedong Yonggungsa","time":"≈ 09:45","number":2,"category":"Templo Budista / Costero","duration":"50 min","timeUsed":["Bajada del furgoneta + caminata por el pasillo de vendedores hasta la plaza de entrada (~10 min)","Los Doce Generales del Zodíaco + Pagoda Sin Accidentes (~10 min)","Descenso de los 108 escalones + sala principal Daeungjeon + terrazas frente al mar (~30 min)","Mirador de la estatua de Haesu Gwaneum + tiempo para fotos (~15 min)","Subida de regreso + reagrupamiento en el furgoneta (~10 min)"],"_poi_meta":{"poi_key":"haedong_yonggungsa","verified":true,"match":"exact","kb_version":"1.24","verified_date":"2026-04-29","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"]},"highlights":["**Fundado en 1376** por el maestro budista Naong Hyegeun (originalmente ''Bomunsa'')","Uno de los muy pocos grandes templos coreanos ubicados junto al mar (la mayoría están en las montañas)","Renombrado **Haedong Yonggungsa en 1974** tras la visión del dragón y la Diosa del monje Jeong-am","**108 escalones de piedra** = las 108 ilusiones de la mente según el budismo","**12 Sibiji-shin (Generales del Zodíaco)** en la entrada; santuario de monedas de la ''**Pagoda Sin Accidentes**''","**Haesu Gwaneum Daebul** (Diosa del Mar de la Misericordia) — la vista del acantilado más fotografiada","Salón principal Daeungjeon restaurado en 1970 con atención a los colores originales","Horario diario 04:30–19:20, entrada GRATUITA; festival de linternas del Cumpleaños de Buda (mayo)","**Alineación de los 12 Generales del Zodíaco Sibiji-shin budistas sobre pilares de piedra en la puerta del templo** — únicos entre los templos costeros coreanos"],"smartNotes":{"photo":"Roca del amanecer en el borde marítimo; las escaleras junto al salón Daeungjeon ofrecen el encuadre clásico de océano y templo; la estatua Haesu Gwaneum desde el acantilado superior ofrece la vista panorámica del templo y el Mar del Este","facilities":"Puestos de souvenirs/aperitivos y pequeña cafetería en la plaza superior; el sendero costero continúa a lo largo de las rocas","tip":"Entradas laterales para acceder a los salones (la puerta principal está reservada para los monjes); el Cumpleaños de Buda (abr–may) trae la exhibición de linternas; llegue antes de las 10:30 para evitar la mayor afluencia de autocares turísticos"},"whyOnRoute":"El punto de referencia icónico de la ruta — el templo más fotografiado de Busan, con 650 años de historia y un entorno budista costero único en Corea. Llegar a las 10:00 permite adelantarse a la avalancha de autocares turísticos (generalmente a partir de las 11:00), de modo que el descenso de los 108 escalones y el mirador de Haesu Gwaneum se pueden recorrer sin hacer cola. La ubicación en la costa noreste también se combina de forma natural con el Cheongsapo Blue Line Park, justo al sur, formando juntos el clúster de la costa este del día antes de que el furgoneta regrese por la ciudad hacia el Cementerio Memorial de la ONU, Gamcheon y Jagalchi.","convenience":{"restroom":"Disponibles cerca de la entrada principal y dentro del recinto","parking":"Aparcamiento de Haedong Yonggungsa (de pago, según la web oficial de Visit Busan)"},"description":"**Haedong Yonggungsa (해동 용궁사) — el templo budista costero más famoso de Corea** — se asienta sobre los acantilados rocosos de Gijang-gun en la costa noreste de Busan, uno de los muy pocos grandes templos coreanos que NO está ubicado en las montañas. Fundado originalmente en **1376 durante la Dinastía Goryeo por el gran maestro budista Naong Hyegeun (나옹 혜근, 1320-1376)** — consejero real y maestro que contribuyó a moldear el budismo coreano en los albores de la era Joseon. \n\nSegún la leyenda, Naong practicaba el ascetismo en el Templo Bunhwangsa en Gyeongju durante una sequía nacional; el dios del Mar del Este se le apareció en sueños y le dijo que construir un templo en el Monte Bongrae (el nombre original de este acantilado costero) restauraría la prosperidad del reino. \n\nNaong fundó el templo y lo llamó **Bomunsa**, dedicado a Gwanseum-bosal (관세음보살, el Bodhisattva de la Compasión). El templo fue destruido durante la **Invasión Japonesa Imjin de 1592** y permaneció en ruinas durante más de 300 años hasta que **el monje Ungang del Templo Tongdosa comenzó la reconstrucción a principios de la década de 1930**. \n\nEl nombre actual, **Haedong Yonggungsa (Templo del Palacio del Dragón Coreano)**, data únicamente de **1974** — cuando el Monje Principal Jeong-am, durante una oración de 100 días (jeong-geon kido), tuvo una visión de la Diosa de la Misericordia descendiendo sobre el lomo de un dragón, emanando luz multicolor. \n\nEl templo fue renombrado en honor a esta visión. La visita sigue el camino procesional característico del templo: a través de la hilera de **12 Sibiji-shin (Doce Generales del Zodíaco)** en la plaza de entrada, pasando la **Pagoda de los 7 Pisos ''Sin Accidentes''** (donde los conductores dejan ofrendas de monedas bajo un santuario de rueda de piedra), bajando los famosos **108 escalones de piedra** (que representan las 108 ilusiones de la mente budista) a través de un pequeño bosque de bambú, y saliendo a las terrazas junto al mar y al salón principal Daeungjeon. \n\nEl **Haesu Gwaneum Daebul** (estatua de la Diosa del Mar de la Misericordia) en el acantilado superior es la vista más fotografiada, enmarcando tanto los tejados del templo como el Mar del Este. Horario: **04:30-19:20 diariamente, última entrada 18:50, ENTRADA GRATUITA**. \n\n**El Cumpleaños de Buda (mayo)** trae exhibiciones del festival de linternas Yeondunhoe.","visitBasics":{"hours":"Diario 04:30–19:20 (última entrada a las 18:50)","closed":"Abierto todo el año","admission":"Gratuito; el aparcamiento para vehículos particulares es de pago","walking":"Moderado — 108 escalones a través de un pinar, múltiples terrazas junto al mar y escaleras"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Templo Haedong Yonggungsa","caption":"Templo Haedong Yonggungsa — photo 1","alt":"Templo Haedong Yonggungsa — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Templo Haedong Yonggungsa","caption":"Templo Haedong Yonggungsa — photo 2","alt":"Templo Haedong Yonggungsa — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Templo Haedong Yonggungsa","caption":"Templo Haedong Yonggungsa — photo 3","alt":"Templo Haedong Yonggungsa — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Templo Haedong Yonggungsa","caption":"Templo Haedong Yonggungsa — photo 4","alt":"Templo Haedong Yonggungsa — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Templo Haedong Yonggungsa","caption":"Templo Haedong Yonggungsa — photo 5","alt":"Templo Haedong Yonggungsa — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Templo Haedong Yonggungsa","caption":"Templo Haedong Yonggungsa — photo 6","alt":"Templo Haedong Yonggungsa — gallery image 6"}]},{"name":"Cementerio Memorial de la ONU en Corea","time":"≈ 11:05","number":3,"category":"Memorial / Historia de Guerra","duration":"30 min","timeUsed":["Bajada del furgoneta + caminata hasta el Pabellón Memorial (~5 min)","Documental de 12 minutos sobre la Guerra de Corea + introducción (~15 min)","Área Simbólica (22 banderas) + Muro del Recuerdo (~20 min)","Recorrido a pie por el recinto + regreso al furgoneta (~20 min)"],"_poi_meta":{"poi_key":"un_memorial_cemetery","verified":true,"match":"exact","kb_version":"1.24","verified_date":"2026-04-29","sources":["UNMCK official","Wikipedia","ABMC","Visit Busan","CNN","VisitKorea","UN Memorial Cemetery in Korea Official Site"]},"highlights":["**El único cementerio memorial de la ONU en el mundo** — establecido en enero de 1951 por el Comando de la ONU","Terreno donado por la República de Corea a las Naciones Unidas en **1959**","**22 naciones contribuyentes** bajo la bandera de la ONU durante la Guerra de Corea (1950-1953)","Actualmente **2.300 tumbas de 11 naciones** (tras la mayoría de las repatriaciones posteriores al armisticio)","**Muro del Recuerdo (2006)**: 40.896 nombres de bajas de la ONU en 140 paneles de mármol","Puerta Principal diseñada por el **arquitecto coreano Kim Joong-up (1966)**","**Ceremonia ''Vuelta hacia Busán''** anualmente el 11 de nov. a las 11:00 AM — homenaje silencioso mundial","Horario diario 09:00-18:00 may-sep / 09:00-17:00 oct-abr; GRATUITO; 100% accesible para sillas de ruedas","**Ceremonia ''Vuelta hacia Busán'' el 11 de noviembre a las 11:00 AM** — el único cementerio memorial de la ONU en el mundo celebra este momento anual de silencio en honor a las 22 naciones contribuyentes"],"smartNotes":{"photo":"Muro del Recuerdo (40.896 nombres en 140 paneles de mármol) y el Área Simbólica donde ondean las banderas de las 22 naciones contribuyentes","facilities":"Memorial Service Hall, Sala de Objetos Conmemorativos, Monumento a las Fuerzas de la ONU, Memorial de la Guerra de Corea de EE.UU. (escultura de Frank Gaylord, 2013) y el adyacente Salón Memorial de Paz de la ONU","tip":"Vea primero el documental de 12 minutos en el Memorial Service Hall (disponible en inglés); vístase con decencia, mantenga la voz baja y no consuma alimentos en el recinto; el terreno es sagrado — no se suba a las tumbas ni a la hierba entre las lápidas"},"whyOnRoute":"El **contrapeso moral** de la ruta — la identidad de Busán es inseparable de su papel como la única ciudad coreana que el Ejército de Corea del Norte nunca capturó durante la guerra (la población aumentó de 880.000 a 1,4 millones a medida que los refugiados huían hacia el sur), y tanto las chabolas de refugiados en las laderas de Gamcheon como la cultura de las ''ajumma'' vendedoras de pescado de Jagalchi se relacionan directamente con esta misma narrativa de la Guerra de Corea. Visitar el UNMCK antes de Gamcheon y Jagalchi proporciona a los visitantes el contexto histórico que convierte el resto de las paradas del día en algo más que simples oportunidades para fotografías. La llegada a las 14:15 también queda holgadamente dentro del cierre vespertino de las 18:00 en may-sep (o las 17:00 en oct-abr).","convenience":{"restroom":"Disponible en el Memorial Service Hall y el centro de visitantes","parking":"Estacionamiento en el lugar — gratuito los primeros 90 min, luego ₩1.200/hr"},"description":"**El Cementerio Memorial de la ONU en Corea (재한유엔기념공원, UNMCK)** es el **único cementerio memorial de las Naciones Unidas en el mundo** — establecido el 18 de enero de 1951 por el Comando de la ONU durante la Guerra de Corea, dedicado el 6 de abril de 1951 por el general estadounidense Matthew Ridgway, y donado formalmente a las Naciones Unidas por la República de Corea en **1959** en agradecimiento por las fuerzas de la ONU que murieron defendiendo Corea del Sur. \n\n**22 naciones contribuyentes participaron en la Guerra de Corea (1950-1953)** bajo la bandera de la ONU — 16 naciones enviaron tropas de combate + 5 enviaron ayuda médica + 1 envió observadores. Inicialmente había hasta **11.000 tumbas**; la mayoría de los caídos fueron repatriados tras el armisticio, quedando hoy **2.300 tumbas de 11 países** (Reino Unido, EE.UU., Türkiye, Canadá, Australia, Países Bajos, Francia, Noruega, Corea del Sur, Nueva Zelanda, Sudáfrica). \n\nLa visita recorre la secuencia monumental principal del cementerio: (1) la **Puerta Principal** (diseñada por el arquitecto coreano Kim Joong-up, construida por la Ciudad de Busán en 1966 — los ocho pilares que soportan el techo simbolizan el momento y la eternidad de la guardia de los soldados); (2) el **Memorial Service Hall** con un documental de 12 minutos en inglés/coreano sobre la historia del cementerio; (3) el **Área Simbólica** donde ondean diariamente las **banderas de las 22 naciones contribuyentes + la bandera coreana + la bandera de la ONU**; (4) el **Muro del Recuerdo**, completado en **2006**, con los **40.896 nombres de bajas de la ONU inscritos en 140 paneles de mármol** — muchos familiares de veteranos encuentran aquí a sus antepasados por primera vez; y (5) el **Memorial de la Guerra de Corea de EE.UU.**, dedicado en **2013** con la escultura de Frank Gaylord encargada por la American Battle Monuments Commission. \n\n**Horario: 09:00-18:00 (may-sep) / 09:00-17:00 (oct-abr); GRATUITO; 100% accesible para sillas de ruedas**. Ceremonia silenciosa anual **''Vuelta hacia Busán''** el 11 de nov. a las 11:00 AM, donde el mundo se vuelve simbólicamente hacia este cementerio.","visitBasics":{"hours":"Diario 09:00–18:00 (may–sep) / 09:00–17:00 (oct–abr)","closed":"Abierto todo el año","admission":"Gratuito","walking":"Fácil — senderos planos de césped y caminos pavimentados en 14 ha de terreno; 100% accesible para sillas de ruedas"},"image":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","images":["/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-43.webp","/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-47.webp"],"imageCredits":[{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","source":"atoc-korea"},{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-43.webp","source":"atoc-korea"},{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-47.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"Cementerio Memorial de la ONU en Corea","caption":"Cementerio Memorial de la ONU en Corea — photo 1","alt":"Cementerio Memorial de la ONU en Corea — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-43.webp","location":"Cementerio Memorial de la ONU en Corea","caption":"Cementerio Memorial de la ONU en Corea — photo 2","alt":"Cementerio Memorial de la ONU en Corea — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-47.webp","location":"Cementerio Memorial de la ONU en Corea","caption":"Cementerio Memorial de la ONU en Corea — photo 3","alt":"Cementerio Memorial de la ONU en Corea — gallery image 3"}]},{"number":4,"time":"≈ 11:50","duration":"40 min","name":"Almuerzo en un restaurante local de Busan (por tu cuenta)","category":"Comida","description":"El **almuerzo está incluido** en un restaurante local de Busan preestablecido por el operador — generalmente un **restaurante de Dwaeji Gukbap (sopa de cerdo con arroz de Busan) en Yeongdo o en el centro de Busan**, o un establecimiento de **Bibimbap / menú coreano** seleccionado por sus asientos grupales, menús en inglés y gestión fiable de alérgenos. \n\nEl Dwaeji Gukbap tiene sus orígenes entre los **refugiados de la Guerra de Corea** en Busan hacia 1950 (cuando los refugiados del norte adaptaron las sopas al estilo de Pyongyang usando huesos de cerdo disponibles) y sigue siendo el plato reconfortante más distintivo de la ciudad. \n\n**Las sustituciones vegetarianas y halal están disponibles con 24 horas de antelación en la reserva** — comunique sus necesidades dietéticas al reservar a través de AtoC Korea directamente. \n\n**Las bebidas (soju, cerveza, refrescos) no están incluidas** — habitualmente entre ₩3.000 y ₩6.000 si se piden.","highlights":["El almuerzo corre por tu cuenta: no está incluido en el precio del tour","**Dwaeji-gukbap** (sopa de hueso de cerdo con arroz) o **milmyeon** (fideos fríos de trigo), dos especialidades de Busan","Ambos platos tienen un origen ligado a los refugiados de la Guerra de Corea, propio de Busan","Precio habitual de 8.000 a 12.000 KRW por plato; bebidas de 3.000 a 6.000 KRW si las pides","Alternativas vegetarianas o halal disponibles si lo indicas al reservar"],"whyOnRoute":"El almuerzo incluido en un restaurante fijo mantiene al grupo pequeño en horario (frente al charter privado, donde el almuerzo de pago propio puede prolongarse más de 90 min). El horario de las 12:15 (frente a las 11:50 del privado) tiene en cuenta el ritmo ligeramente más ágil del restaurante fijo.","_poi_meta":{"poi_key":"OPS_busan_lunch","kb_version":"1.15","verified_date":"2026-04-29"},"visitBasics":{"hours":"Depende del restaurante (servicio de almuerzo habitual de 11:30 a 14:30)","closed":"Varía según el establecimiento; el conductor confirma disponibilidad","admission":"Pago directo, ~₩10.000–25.000 por persona; el almuerzo NO está incluido en el precio del tour","walking":"Mínimo — restaurante a menos de 5 min a pie del punto de bajada del vehículo"},"convenience":{"restroom":"Dentro del restaurante","parking":"El conductor deja a los pasajeros y espera en la parada legal más cercana"},"smartNotes":{"photo":"El Dwaeji Gukbap (sopa de cerdo con arroz, el plato reconfortante emblema de Busan de la época de los refugiados de la Guerra de Corea) o el Milmyeon (la respuesta de Busan en fideos de trigo al naengmyeon norcoreano, originado en las cocinas de los refugiados de los años 50) ofrecen las imágenes gastronómicas locales más representativas.","tip":"**Las solicitudes vegetarianas / halal / por alérgenos requieren 24 h de antelación**. El conductor recomienda según las preferencias del grupo (coreano / marisco / internacional); siga la recomendación o solicite una cocina específica en el recogida matutina."}},{"name":"Mercado de Pescado Jagalchi","time":"≈ 12:45","number":5,"category":"Mercado de Pescado / Cultura Local","duration":"30 min","timeUsed":["Bajada del furgoneta + caminata al edificio principal (~5 min)","Recorrido por la planta baja de mariscos vivos con comentarios del guía (~20 min)","Muelle exterior + pasillos de mariscos secos (~10 min)","Reagrupamiento + breve caminata hacia la Plaza BIFF (~5 min)"],"_poi_meta":{"poi_key":"jagalchi_market","verified":true,"match":"exact","kb_version":"1.24","verified_date":"2026-04-29","sources":["VisitKorea","Wikipedia","Visit Busan","Hungry Pursuit","Emma Jane Explores","Jagalchi.org","Korean Heritage Service / Cultural Heritage Administration"]},"highlights":["**El mayor mercado de mariscos de Corea** — cubre 66.000 m² con ~400 vendedores","**''Jagalchi''** = ''grava'' (자갈) por la orilla pedregosa original","**''Jagalchi Ajumma''** = mujeres vendedoras de pescado viudas o desplazadas tras la Guerra de Corea — ícono de Busan","**Compra el pescado en el 1.er piso → cocínalo arriba en el 2.º piso** con una pequeña tarifa de cocina = la forma local","**Moderno edificio con forma de gaviota, reabierto en 2006**","**Festival Cultural y Turístico de Jagalchi** anual en octubre","Muelle exterior y Sky Park (5.º piso cuando está abierto) para fotos junto al mar","Horario diario 05:00-22:00; **CERRADO el 1.er y 3.er martes** de cada mes","**El moderno edificio principal con forma de gaviota, reabierto en 2006**, abarca ~66.000 m² con ~400 vendedores; **cerrado el 1.er y 3.er martes** de cada mes (nota operativa clave para la planificación del itinerario)"],"smartNotes":{"photo":"Muelle exterior detrás del edificio para la foto del puerto y los barcos de pesca; ajummas de Jagalchi en los puestos de peces vivos (pide siempre permiso antes de fotografiar)","facilities":"1.er piso: marisco vivo; 2.º piso: sashimi y restaurantes; sección de pescado seco; Sky Park en la azotea (cuando está abierto); Bufé del Centro de Sashimi en el 5.º piso","tip":"Compra el pescado en el 1.er piso y llévalo arriba a un restaurante del 2.º piso pagando una pequeña tarifa de cocina — así se hace aquí; dirección: 52 Jagalchihaean-ro, Jung-gu; el suelo está mojado — se recomienda calzado cerrado; el efectivo funciona mejor que las tarjetas en los puestos más pequeños"},"whyOnRoute":"La identidad de Busan se construye sobre el marisco igual que la de Seúl sobre la cocina palaciega Joseon, y Jagalchi es su expresión más esencial. Además está a la entrada del bloque de Nampo-dong, y por eso el centro del día pivota aquí: Jagalchi, la plaza BIFF y el mercado Gukje son tres paradas distintas dentro de un radio de 600 m, hechas a pie y no en carretera.","convenience":{"restroom":"Disponible dentro del edificio principal en cada planta","parking":"Aparcamiento en el sótano del edificio principal, ₩700 / 10 min"},"description":"**Mercado Jagalchi (자갈치시장)** — **el mayor mercado de mariscos de Corea** y uno de los diez hitos de Busan — se sitúa en el paseo marítimo del Puerto de Nampo, en Jung-gu, a 7 minutos a pie de la Estación Jagalchi (Línea 1) o de la Estación Nampo. \n\nEl nombre **''Jagalchi''** proviene de **''jagal'' (자갈, grava)**, en referencia a la orilla pedregosa que bordeaba la zona. El carácter moderno del mercado se forjó tras la **Guerra de Corea (1950-1953)**: cuando muchos hombres estaban combatiendo o habían perecido en combate, **mujeres viudas y desplazadas — las legendarias ''Ajumma de Jagalchi'' (자갈치 아주머니)** — se convirtieron en el sostén de sus familias vendiendo pescado sobre cajas de madera a lo largo del muelle. \n\nLas ajumma han sido el **alma económica y cultural de Busan desde entonces**, encarnando tanto la historia de recuperación de la posguerra de la ciudad como la cultura coreana del ''**jeong (정)**'', ese vínculo de confianza personal a largo plazo entre vendedor y cliente. \n\nEl actual **edificio principal con forma de gaviota reabrió en 2006** y alberga a ~400 vendedores en 66.000 m² de superficie bruta: la **planta baja (1F)** es el mercado de mariscos vivos (pulpo, cangrejo de las nieves, abulón, tunicados, anguilas babosas vivas, caballa, pepinos de mar, lenguados de calidad para hoe) donde los visitantes pueden **comprar marisco fresco por peso y llevarlo al restaurante de la planta superior (2F) por una pequeña tarifa de cocinado** — así es como comen los locales en Jagalchi. \n\nLa **2F** es el nivel de sashimi y restaurantes. La sección de mariscos secos (anchoas, alga laver, algas kombu, calamar seco) se extiende a lo largo del muelle exterior y es la más fotogénica para instantáneas de viaje. \n\n**Horario: diariamente 05:00-22:00; CERRADO el 1er y 3er martes de cada mes**. **Festival Anual de Turismo Cultural de Jagalchi** cada octubre. \n\nEl tiempo de visita está deliberadamente programado durante la calma de última hora de la tarde (después de la afluencia del almuerzo y antes de la del anochecer) para que los pasillos y el **Parque Cielo** de la azotea sean cómodos para pasear.","visitBasics":{"hours":"Diario 05:00–22:00 (el horario de los vendedores varía; sección de peces vivos oficialmente 06:00–22:00)","closed":"1.er y 3.er martes de cada mes","admission":"Entrada gratuita; pago por consumo en mariscos y tarifa de cocina en el 2.º piso","walking":"Moderado — planta baja nivelada (húmeda, puede ser resbaladiza); escaleras al nivel de sashimi/restaurantes del 2.º piso"},"image":"/images/itinerary/jagalchi-harbor-sign.webp","images":["/images/itinerary/jagalchi-harbor-sign.webp","/images/itinerary/jagalchi-market-interior.webp","/images/itinerary/jagalchi-night-building.webp","/images/tours/jagalchi-market/photo-001.webp","/images/tours/jagalchi-market/photo-002.webp","/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","/images/tours/jagalchi-market/photo-010.webp","/images/tours/jagalchi-market/jagalchi-building-facade-night.webp","/images/tours/jagalchi-market/jagalchi-entrance-arch-night.webp","/images/tours/jagalchi-market/jagalchi-i-love-sign-harbor.webp","/images/tours/jagalchi-market/jagalchi-interior-foreign-tourists.webp","/images/tours/jagalchi-market/jagalchi-seafood-baskets-kto.webp"],"imageCredits":[{"url":"/images/itinerary/jagalchi-harbor-sign.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-market-interior.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-night-building.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/photo-001.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/photo-002.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/photo-010.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-building-facade-night.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-entrance-arch-night.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-i-love-sign-harbor.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-interior-foreign-tourists.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-seafood-baskets-kto.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/photo-001.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/photo-002.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","source":"atoc-korea"},{"url":"/images/tours/jagalchi-market/photo-010.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 1","alt":"Mercado de Pescado Jagalchi — gallery image 1"},{"id":2,"type":"photo","src":"/images/itinerary/jagalchi-market-interior.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 2","alt":"Mercado de Pescado Jagalchi — gallery image 2"},{"id":3,"type":"photo","src":"/images/itinerary/jagalchi-night-building.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 3","alt":"Mercado de Pescado Jagalchi — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/jagalchi-market/photo-001.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 4","alt":"Mercado de Pescado Jagalchi — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/jagalchi-market/photo-002.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 5","alt":"Mercado de Pescado Jagalchi — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 6","alt":"Mercado de Pescado Jagalchi — gallery image 6"},{"id":7,"type":"photo","src":"/images/tours/jagalchi-market/photo-010.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 7","alt":"Mercado de Pescado Jagalchi — gallery image 7"},{"id":8,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-building-facade-night.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 8","alt":"Mercado de Pescado Jagalchi — gallery image 8"},{"id":9,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-entrance-arch-night.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 9","alt":"Mercado de Pescado Jagalchi — gallery image 9"},{"id":10,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-i-love-sign-harbor.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 10","alt":"Mercado de Pescado Jagalchi — gallery image 10"},{"id":11,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-interior-foreign-tourists.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 11","alt":"Mercado de Pescado Jagalchi — gallery image 11"},{"id":12,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-seafood-baskets-kto.webp","location":"Mercado de Pescado Jagalchi","caption":"Mercado de Pescado Jagalchi — photo 12","alt":"Mercado de Pescado Jagalchi — gallery image 12"}]},{"name":"Plaza BIFF","time":"≈ 13:15","number":6,"category":"Distrito del Cine / Comida callejera","duration":"20 min","timeUsed":["Caminata de Jagalchi a la Plaza BIFF (~5 min)","Huellas de directores en la Calle de las Estrellas (~10 min)","Opcional: ssiat-hotteok u otro aperitivo callejero (~10 min)"],"_poi_meta":{"match":"exact","poi_key":"biff_square","sources":["Visit Busan","VisitKorea","Busan International Film Festival official","Wikipedia"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Designada en 1996** para conmemorar el **Festival Internacional de Cine de Busan (BIFF)** — el festival de cine más grande de Asia, celebrado por primera vez en septiembre de 1996","Corredor de **428 metros de la Calle de las Estrellas** a través del antiguo distrito de cines de Nampo-dong","**Huellas de directores y actores** incrustadas en el pavimento (Park Chan-wook, Bong Joon-ho, Kim Ki-duk, Im Kwon-taek e invitados internacionales desde 1996)","**Ssiat Hotteok (씨앗호떡)** — el emblemático panqueque dulce relleno de semillas de la Plaza BIFF (girasol, sésamo, calabaza); originario de este lugar","**La calle de cines más antigua de Corea** — el Teatro Bumin (1924) y el Teatro Joongan (1927) inauguraron el distrito","Adyacente al Mercado Jagalchi (3 min a pie) y al Mercado Gukje (2 min a pie)","Calle peatonal al aire libre, entrada gratuita, zona pública las 24 h"],"smartNotes":{"tip":"Prueba el **ssiat-hotteok** en el puesto marcado como ''시아갓호떡'' — el puesto original de la Plaza BIFF, ₩2.000–3.000 cada uno; cómelo con cuidado ya que el relleno de semillas y azúcar permanece muy caliente dentro de la masa","photo":"Placas con huellas de directores en el pavimento (busca las estrellas de bronce con nombres y el año BIFF); el arco ceremonial de la Plaza PIFF en la entrada de Nampo-dong","facilities":"Baños públicos dentro de los grandes almacenes Lotte adyacentes y en el vestíbulo del cine CGV Plaza BIFF; cajeros automáticos en Gwangbok-ro"},"whyOnRoute":"La Plaza BIFF es el conector natural entre Jagalchi y el Mercado Gukje — los tres se encuentran dentro del núcleo de Nampo-dong y pueden recorrerse de extremo a extremo en menos de 10 minutos. Incluir la Plaza BIFF como parada breve independiente (en lugar de utilizarla como simple tramo de tránsito) reconoce la identidad de Busan como **la ciudad anfitriona del festival de cine más grande de Asia** desde 1996 — la industria cinematográfica coreana tiene aquí su cara pública. La parada de 25 minutos se adapta al ritmo del tour en vehículo y ofrece a los visitantes tiempo para un ssiat-hotteok y un paseo junto a las placas de directores más fotografiadas. La calle peatonal diseñada para caminar mantiene la parada adaptada al furgoneta: el furgoneta se reposiciona hacia el punto de bajada del Mercado Gukje mientras los visitantes recorren el corredor.","convenience":{"parking":"Sin aparcamiento para autocares dentro de la Plaza BIFF (calle peatonal); el furgoneta se reposiciona hacia el Mercado Gukje mientras los visitantes atraviesan la zona","restroom":"Grandes almacenes Lotte sucursal Gwangbok-ro (baños públicos gratuitos) y vestíbulo del cine CGV Plaza BIFF"},"description":"**La plaza BIFF (비프광장, antes plaza PIFF)** es un **corredor peatonal de 428 metros** en Nampo-dong, distrito de Jung-gu, bautizado en **agosto de 1996** para conmemorar el nacimiento del **Festival Internacional de Cine de Busan (BIFF)**, el mayor festival de cine de Asia, celebrado por primera vez aquel septiembre.\n\nLa plaza ocupa lo que históricamente fue **la calle de cines más antigua de Corea**: el **teatro Bumin abrió aquí en 1924** y el **teatro Joongan en 1927**, durante el periodo colonial japonés, y desde entonces la zona ha sido el corazón de la exhibición cinematográfica del país.\n\nSu rasgo más característico es la **Star Street**: placas de bronce y mármol embutidas en el pavimento con huellas de manos, autógrafos y años de nacimiento de directores y actores coreanos de proyección internacional — Park Chan-wook, Bong Joon-ho, Kim Ki-duk, Im Kwon-taek, Choi Min-sik — y de invitados extranjeros, incluidos miembros de jurados de festivales. En la entrada de Nampo-dong se alza el **arco conmemorativo de la plaza PIFF**, que enmarca el ángulo más fotografiado.\n\nLa plaza BIFF es además la cuna del **ssiat hotteok (씨앗호떡)**: la variante de Busan del hotteok coreano, en la que el disco de masa se abre tras freírse y se rellena con semillas mezcladas — girasol, sésamo, calabaza, cacahuete — y azúcar moreno. Es un clásico invernal de la calle en Busan que se ha extendido por todo el país desde los años 2000.\n\nHoy el corredor gira en torno a las salas de **CGV BIFF Square**, **Daeyoung Cinema** y **Megabox**, con los **grandes almacenes Lotte de Gwangbok-ro** a un minuto a pie. Es una **calle peatonal gratuita, al aire libre y abierta 24 horas**; el momento más concurrido es **el propio festival, diez días cada octubre**, cuando pantallas temporales, alfombras rojas y coloquios con directores llenan el corredor.","visitBasics":{"hours":"Calle peatonal abierta las 24 h; puestos de ssiat-hotteok habitualmente de 10:00 a 22:00","closed":"Abierto todo el año; mayor afluencia durante el festival BIFF (octubre)","walking":"Fácil — calle peatonal llana y pavimentada","admission":"Gratuito"},"image":"/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","images":["/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","/images/tours/biff-square/biff-square-arch-ai.webp","/images/tours/biff-square/biff-square-arch-day.webp","/images/tours/biff-square/biff-street-food-collage.webp"],"imageCredits":[{"url":"/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","source":"atoc-korea"},{"url":"/images/tours/biff-square/biff-square-arch-ai.webp","source":"atoc-korea"},{"url":"/images/tours/biff-square/biff-square-arch-day.webp","source":"atoc-korea"},{"url":"/images/tours/biff-square/biff-street-food-collage.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","location":"Plaza BIFF","caption":"Plaza BIFF — photo 1","alt":"Plaza BIFF — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/biff-square/biff-square-arch-ai.webp","location":"Plaza BIFF","caption":"Plaza BIFF — photo 2","alt":"Plaza BIFF — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/biff-square/biff-square-arch-day.webp","location":"Plaza BIFF","caption":"Plaza BIFF — photo 3","alt":"Plaza BIFF — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/biff-square/biff-street-food-collage.webp","location":"Plaza BIFF","caption":"Plaza BIFF — photo 4","alt":"Plaza BIFF — gallery image 4"}]},{"name":"Mercado Gukje","time":"≈ 13:35","number":7,"category":"Mercado Tradicional / Patrimonio de la Guerra de Corea","duration":"25 min","timeUsed":["Caminar desde la Plaza BIFF hasta la entrada del Mercado Gukje (~2 min)","Calle Arirang + callejón de cosméticos (~10 min)","Calle Gongguk + callejones de utensilios de cocina (~10 min)","Vistazo al Mercado Bupyeong Kkangtong (~5 min)","Caminata hasta el punto de recogida del furgoneta en Daecheong-ro (~3 min)"],"_poi_meta":{"match":"exact","poi_key":"gukje_market","sources":["Visit Busan","VisitKorea","Wikipedia","Busan Metropolitan City heritage records"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Fundado entre 1945 y 1950** por comerciantes de la posguerra y **refugiados de la Guerra de Corea** que huyeron al sur desde Corea del Norte","**El nombre ''Gukje (국제) = Internacional''** — refleja la era del mercado negro de posguerra, cuando los productos provenían de los economatos (PX) de las tropas estadounidenses e importaciones de ayuda humanitaria mundial","**Cuadrícula de ~600 m × 100 m con más de 1.500 puestos** — uno de los mercados tradicionales más grandes de Corea","**Seis callejones temáticos**: Calle Arirang (ropa), Calle Gongguk (utensilios de cocina), Calle de la Madera (madera), Calle de la Cosmética, Calle de la Ferretería y Callejón de la Comida","**Mercado Bupyeong Kkangtong** adyacente («Mercado de las Latas») — el primer mercado nocturno de Corea, popular por la comida callejera tras el atardecer","Escenario de la película coreana de 2014 **''Oda a mi padre'' (국제시장)** — 14 millones de entradas vendidas, referente del cine coreano sobre memorias familiares de la Guerra de Corea","Horario habitual de 09:30 a 19:30 todos los días; muchas tiendas cierran los **1.º y 3.º domingos** (varía según la sección)"],"smartNotes":{"tip":"Lleve **efectivo en billetes de baja denominación** (billetes de ₩1.000 y ₩5.000) — la mayoría de los puestos no aceptan tarjetas y prefieren no cambiar billetes de ₩50.000; el regateo moderado es habitual en los puestos de ropa y accesorios, pero no en los callejones de comida; lleve su propia bolsa — las bolsas desechables tienen un coste adicional","photo":"El estrecho corredor de la Calle Arirang repleto de ropa colgante; los luminosos letreros del mercado nocturno Bupyeong Kkangtong (especialmente fotogénico después de las 17:00 en invierno); el arco de entrada en Daecheong-ro","facilities":"Baños públicos dentro del edificio adyacente Bupyeong Kkangtong; cajeros automáticos a lo largo de Daecheong-ro"},"whyOnRoute":"El Mercado Gukje completa el clúster de tres paradas del centro de Nampo-dong (Jagalchi → BIFF → Gukje) y representa el contacto más directo del día con la **historia de los refugiados de la posguerra de la Guerra de Corea** — visible para los visitantes a pie de calle, en lugar de ser narrada desde un memorial. La conexión con el Cementerio Memorial de la ONU visitado por la mañana es intencionada: el Mercado Gukje es el lugar donde los refugiados que sobrevivieron a la Guerra de Corea reconstruyeron la economía de Busan desde cero, con productos intercambiados a través de los economatos de las tropas estadounidenses y los envíos de ayuda de la ONU. Donde Jagalchi muestra la cultura gastronómica coreana y la Plaza BIFF muestra la cultura cinematográfica coreana, el Mercado Gukje muestra la **cultura económica y de supervivencia coreana**. La parada de 30 minutos es suficiente para recorrer los corredores de Arirang y Gongguk y echar un vistazo al mercado nocturno adyacente Bupyeong Kkangtong (de las Latas).","convenience":{"parking":"Sin aparcamiento de autocares dentro del mercado (zona peatonal); el furgoneta recoge a los pasajeros en Daecheong-ro, en la salida norte del mercado","restroom":"Baños públicos dentro del edificio del Mercado Bupyeong Kkangtong; sucursal Gwangbok-ro de los Grandes Almacenes Lotte en las inmediaciones"},"description":"**El mercado Gukje (국제시장, ''Mercado Internacional'')** es un extenso mercado tradicional de Jung-gu, en Busan: uno de los mayores y más antiguos mercados de posguerra de Corea, con una **cuadrícula de unos 600 m x 100 m y más de 1.500 puestos**.\n\nSus orígenes se remontan a **1945**, tras la liberación, cuando comerciantes coreanos desplazados empezaron a vender en el solar que dejaron los japoneses al marcharse, y a la **Guerra de Corea (1950-1953)**, cuando las grandes oleadas de refugiados que huían del norte ampliaron el mercado y consolidaron el nombre de **''mercado Gukje (Internacional)''** que conocemos hoy. El nombre refleja la **era del mercado negro de posguerra**, cuando llegaban mercancías de los economatos PX de las tropas estadounidenses, envíos de ayuda de la ONU e importaciones imposibles de conseguir por los cauces normales.\n\nCuando el **gran incendio de la estación de Busan de 1953** destruyó el distrito comercial contiguo, los comerciantes desplazados se instalaron definitivamente en Gukje, lo que afianzó su predominio.\n\nEl mercado se organiza en **seis calles temáticas**: **Arirang** (ropa y complementos), **Gongguk** (menaje y hogar), **calle de la Madera** (madera y muebles, la especialidad original de los años cincuenta), **calle de la Cosmética**, **calle de la Ferretería** y el **callejón de la Comida**, con puestos de aperitivos y productos típicos de Busan.\n\nJunto a Gukje está el **mercado Bupyeong Kkangtong (부평깡통시장, ''mercado de las latas'')**, llamado así por la cultura de trueque de conservas de los años cincuenta y reconocido como **el primer mercado nocturno oficial de Corea**, iluminado y activo hasta cerca de las 22:00.\n\nEl mercado fue el escenario de la película coreana **''Ode to My Father'' (국제시장, 2014)**, una superproducción sobre la memoria familiar de la guerra que vendió **14 millones de entradas** y sirvió de ajuste de cuentas nacional con los sacrificios de la generación refugiada.\n\nHoy Gukje y Bupyeong forman juntos el distrito comercial más vivido de Busan, usado a diario por los locales y no solo por turistas. **Horario: la mayoría de las tiendas abren de 09:30 a 19:30 todos los días; muchas cierran el primer y el tercer domingo** (varía según la sección).","visitBasics":{"hours":"Generalmente de 09:30 a 19:30 todos los días (varía según la tienda)","closed":"Muchas tiendas cierran los 1.º y 3.º domingos (depende de la sección)","walking":"Fácil–moderado — callejones planos y pavimentados; puede estar concurrido","admission":"Entrada libre"},"image":"/images/itinerary/gukje-market-arcade-sign-forest.webp","images":["/images/itinerary/gukje-market-arcade-sign-forest.webp","/images/itinerary/gukje-market-fresh-produce-aisle.webp"]},{"name":"Pueblo Cultural de Gamcheon","time":"≈ 14:20","number":8,"category":"Pueblo Cultural / Arte Mural","duration":"45 min","timeUsed":["Bajada del furgoneta en el Aparcamiento Público n.º 2 + caminata hasta la entrada (~5 min)","Centro de Información Turística + compra del Mapa de Sellos (~10 min)","Mirador del Jardín del Cielo + banco del Principito (~30 min)","Paseo por el callejón frente a los murales + pausa en una pequeña cafetería (~30 min)","Reunión en el furgoneta (~15 min)"],"_poi_meta":{"poi_key":"gamcheon_culture_village","verified":true,"match":"exact","kb_version":"1.24","verified_date":"2026-04-29","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"]},"highlights":["**''La Machu Picchu de Corea'' / ''La Santorini de Corea''** — Premio Paisaje Urbano Asiático de ONU-Hábitat 2012","Orígenes: **décadas de 1920-1930** reubicación administrativa de Busan + **refugiados Taegeukdo de 1955** (~800 familias)","**La filosofía Taegeukdo de ''permitir que otros prosperen''** = ninguna casa bloquea la vista de la que está detrás","**2009 ''Soñando con Machu Picchu'' + 2010 ''Miro Miro''** — proyectos de arte público del Ministerio de Cultura","**Banco del ''Principito y el Zorro''** en el Jardín del Cielo — el rincón más fotografiado del pueblo","**~1,4 millones de visitantes anuales** desde la revitalización del arte público","**Comunidad residencial viva** — hablar en voz baja, no usar drones, no fotografiar el interior de las casas","Entrada al pueblo gratuita; Mapa de Sellos opcional ~₩2.000","**Premio Paisaje Urbano Asiático de ONU-Hábitat 2012** — reconocimiento al proyecto artístico de 2009 ''Soñando con Machu Picchu'' que transformó el asentamiento de refugiados Taegeukdo de 1955 en el emblemático pueblo de murales de Busan"],"smartNotes":{"photo":"Banco del Principito y el Zorro (larga cola de espera) y Haneul Maru / Observatorio del Jardín del Cielo para vistas panorámicas de los tejados de colores y la bahía","facilities":"Alquiler de hanbok, talleres de artesanía, puestos de caramelos coreanos, cafeterías; pequeño museo del pueblo en la entrada; el mapa de sellos es la manera más sencilla de orientarse","tip":"Aquí vive gente: baja la voz, nada de drones y llévate tu basura; usa calzado con buen agarre para las cuestas. El pueblo está más tranquilo a primera hora de la tarde, cuando los grupos de la mañana ya se han ido."},"whyOnRoute":"La parada más colorida del recorrido; no hay otro barrio así en Corea. El hilo de la Guerra de Corea lo atraviesa entero: el Cementerio Conmemorativo de la ONU es el memorial y Gamcheon es la consecuencia vivida, un asentamiento de refugiados convertido en comunidad. Cuarenta y cinco minutos bastan para el recorrido fotográfico principal, del mirador hacia abajo por los callejones pintados.","convenience":{"restroom":"Aseos públicos en el Centro de Información Turística y cerca de los principales miradores","parking":"Aparcamiento Público de Gamcheon nº 2 (de pago)"},"description":"**El Pueblo Cultural de Gamcheon (감천문화마을)** — apodado tanto **''el Machu Picchu de Corea''** como **''la Santorini de Corea''** — es un barrio en ladera en Saha-gu, al oeste de Busán, cuyas casas pintadas en colores pastel descienden en hileras escalonadas por la pendiente. \n\nEl asentamiento comenzó en las **décadas de 1920-1930** cuando la administración de Busán reubicó a residentes de clase trabajadora alejándolos del puerto. \n\nEl carácter del pueblo quedó definido en **1955** cuando **~800 familias (unas 4.000 personas) de la comunidad religiosa Taegeukdo** — una religión sincrética únicamente coreana que mezcla elementos budistas, confucianos y del yin-yang, fundada por **Jo Cheol-je** durante el período colonial japonés — se asentaron aquí como refugiados de la Guerra de Corea que huían del Norte. \n\nLa filosofía Taegeukdo de ''**permitir que los demás prosperen**'' modeló directamente la característica más distintiva del pueblo: las casas están intencionalmente escalonadas de modo que **ningún techo bloquee la vista de la casa que hay detrás**, con toda la comunidad visible hacia el cielo y el mar. \n\nGamcheon siguió siendo uno de los barrios más pobres de Busán hasta **2009**, cuando el Ministerio de Cultura de Corea lanzó el proyecto de revitalización de arte público **''Soñando con Machu Picchu en Busán''**, seguido del **proyecto ''Miro Miro'' (laberinto) en 2010** — añadiendo más de 22 murales, esculturas e instalaciones artísticas encargadas, incluido el icónico **banco del ''Principito y el Zorro''** en el mirador del Sky Garden. \n\nGamcheon ganó el **Premio al Paisaje Urbano Asiático de ONU-HABITAT 2012** y ahora recibe **~1,4 millones de visitantes anuales**. La visita sigue la emblemática ruta de caminata con mapa de sellos del pueblo: desde la entrada en el **Centro de Información Turística**, hasta el **mirador Sky Garden** para la fotografía panorámica de los tejados de colores del arcoíris, luego por los laberínticos callejones pasando por murales, tiendas de alquiler de hanbok, talleres de artesanía y pequeños cafés. \n\n**El pueblo es una comunidad residencial viva** — se requiere hablar en voz baja, no se permiten drones, no se hacen fotografías con flash dentro de las casas y la basura debe retirarse. Horario **09:00-18:00 mar-oct / 09:00-17:00 nov-feb (centro de información)**; **el pueblo en sí está abierto 24h, entrada GRATUITA**.","visitBasics":{"hours":"Diariamente 09:00–18:00 (mar–oct) / 09:00–17:00 (nov–feb); algunas tiendas y cafeterías tienen su propio horario","closed":"Abierto todo el año (comunidad residencial viva)","admission":"Entrada al pueblo gratuita; Mapa de Sellos opcional ≈ 2.000 KRW","walking":"Exigente físicamente — callejones y escaleras muy empinados; en muchas secciones no es apto para cochecitos ni sillas de ruedas"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/itinerary/jagalchi-harbor-sign.webp","/images/itinerary/jagalchi-market-interior.webp","/images/itinerary/jagalchi-night-building.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-harbor-sign.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-market-interior.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-night-building.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 1","alt":"Pueblo Cultural de Gamcheon — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 2","alt":"Pueblo Cultural de Gamcheon — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 3","alt":"Pueblo Cultural de Gamcheon — gallery image 3"},{"id":4,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 4","alt":"Pueblo Cultural de Gamcheon — gallery image 4"},{"id":5,"type":"photo","src":"/images/itinerary/jagalchi-market-interior.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 5","alt":"Pueblo Cultural de Gamcheon — gallery image 5"},{"id":6,"type":"photo","src":"/images/itinerary/jagalchi-night-building.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 6","alt":"Pueblo Cultural de Gamcheon — gallery image 6"},{"id":7,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Pueblo Cultural de Gamcheon","caption":"Pueblo Cultural de Gamcheon — photo 8","alt":"Pueblo Cultural de Gamcheon — gallery image 8"}]},{"number":9,"time":"≈ 15:25","duration":"20 min","name":"Pasarela Songdo Cloud Trails","category":"Pasarela sobre el mar","description":"**Songdo Cloud Trails (송도구름산책로)** es una **pasarela curva de 365 metros** que se adentra en el mar desde el extremo este de la playa de Songdo. Inaugurada en **2016**, sustituyó a la antigua Songdo Skywalk con una plataforma más larga y serpenteante que termina en un pequeño mirador insular, y es **gratuita y está abierta las 24 horas**.\n\nLa playa donde arranca es la **primera playa pública moderna de Corea**, abierta en **1913**: una media luna de arena fina de 800 m por 50 m en la costa suroeste de Busan, en el distrito de Seo-gu. Algunos tramos tienen suelo de cristal, así que ves el agua moverse justo debajo de ti.","highlights":["**Pasarela curva de 365 m sobre el mar**, inaugurada en 2016 — sustituyó a la antigua Songdo Skywalk","Tramos con suelo de cristal; termina en un pequeño mirador insular","**Gratuita y abierta 24 horas** — sin entrada y sin cola","Arranca en la **primera playa pública moderna de Corea** (abierta en **1913**), 800 m x 50 m de arena fina","Desde el extremo oeste continúan el puente colgante Songdo Yonggung y el sendero costero del parque Amnam"],"timeUsed":["Bajada en el parque marino de Songdo y paseo hasta la entrada de la pasarela (~4 min)","Ida y vuelta por los 365 m de plataforma hasta el mirador insular (~12 min)","Fotos en el paseo marítimo (~4 min)"],"whyOnRoute":"Después del denso bloque de Nampo-dong y de las escaleras de la ladera de Gamcheon, Songdo es la pausa marina del día. La pasarela es **gratuita, llana y se recorre en unos veinte minutos**, así que es la única experiencia de Songdo que todos los pasajeros pueden completar dentro de la parada, decidan o no subir después en el teleférico.","smartNotes":{"tip":"La plataforma está expuesta al mar, puede hacer mucho viento y se cierra con temporal; en ese caso el guía la cambia por el paseo marítimo.","photo":"La curva de la plataforma sobre las olas rompiendo; los paneles de suelo de cristal mirando hacia abajo; los pilonos del teleférico alzándose tras la playa.","facilities":"Aseos públicos en el centro de visitantes del parque marino de Songdo; tiendas de conveniencia a lo largo de Songdohaebyeon-ro."},"convenience":{"parking":"Aparcamiento público del parque marino de Songdo","restroom":"Centro de visitantes del parque marino de Songdo y tiendas de conveniencia de Songdohaebyeon-ro"},"visitBasics":{"hours":"Abierta 24 horas","closed":"Cerrada con viento fuerte o temporal","walking":"Fácil — plataforma llana, sin escaleras","admission":"Gratuita"},"image":"/images/tours/songdo-beach/songdo-skywalk-v-bridge.webp","images":["/images/tours/songdo-beach/songdo-skywalk-v-bridge.webp","/images/tours/songdo-beach/songdo-beach-sign-couple.webp"],"_poi_meta":{"match":"exact","poi_key":"songdo_beach","sources":["Visit Busan","VisitKorea","Songdo Marine Cable Car official","Busan Seo-gu Cultural Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"}},{"number":10,"time":"≈ 15:45","duration":"25 min","name":"Songdo Sky Park (parque Amnam)","category":"Parque del cabo / teleférico opcional","description":"**Songdo Sky Park** está en el cabo del parque Amnam, en el extremo opuesto del **teleférico marino de Songdo (Busan Air Cruise)**: una línea de **1,62 km** de ida y vuelta que cruza la bahía a hasta **86 m** sobre el agua. Funcionó por primera vez en 1964, cerró en 1988 y **reabrió en junio de 2017**.\n\nEl parque de arriba tiene miradores sobre el mar que devuelven la vista a la playa de Songdo al otro lado de la bahía, paseos ajardinados y una zona temática de dinosaurios a la que los niños van directos. Desde los miradores el sendero costero sigue bajando hacia el parque Amnam propiamente dicho.\n\n**El teleférico no está incluido en esta excursión.** Es una elección que se hace y se paga en la propia estación: **17.000 KRW ida y vuelta por adulto**, o **25.000 KRW** por la cabina Crystal con suelo de cristal. Quien prefiera quedarse a nivel del mar pasa la parada en el paseo marítimo; el vehículo espera en cualquier caso.","highlights":["**Teleférico marino de Songdo (Busan Air Cruise)** — 1,62 km ida y vuelta, hasta **86 m** sobre la bahía","Línea inaugurada en 1964, cerrada en 1988, **reabierta en junio de 2017**","Opción de **cabina Crystal** con suelo de cristal","Miradores sobre el mar en el cabo del parque Amnam, con vista de vuelta a la bahía","Zona temática de dinosaurios; el sendero costero continúa hacia el parque Amnam","**El teleférico se elige y se paga in situ: 17.000 KRW ida y vuelta por adulto, 25.000 KRW la cabina Crystal**"],"timeUsed":["Cola de billetes en la estación base de Songdo (~5 min)","Travesía en teleférico hasta la estación del parque Amnam (~7 min por trayecto)","Miradores del Sky Park (~10 min)"],"whyOnRoute":"Es la única parada del día en la que la experiencia la elige el pasajero. El Sky Park está al otro lado de la bahía y el teleférico es la forma de subir, así que la parada está dimensionada para el trayecto de ida y vuelta. Quien no suba tampoco se queda esperando en un sitio incómodo: la estación base está en la misma playa que el grupo acaba de recorrer.","smartNotes":{"tip":"Compra en la estación base; la cola de la cabina Crystal suele ser más larga que la normal. Si tu barco tiene un all-aboard temprano, sube primero y fotografía desde arriba en lugar de entretenerte abajo.","photo":"La bahía desde la mitad de la travesía; los miradores del Sky Park mirando hacia la playa de Songdo; el suelo de cristal de la cabina Crystal sobre mar abierto.","facilities":"Cafetería y exposición conmemorativa de la Guerra de Corea en la estación baja; aseos en ambas estaciones."},"convenience":{"parking":"Aparcamiento público del parque marino de Songdo (estación base)","restroom":"Ambas estaciones del teleférico"},"visitBasics":{"hours":"Teleférico 09:00-21:00 (según temporada); el cabo del parque Amnam abre a diario","closed":"Teleférico suspendido con viento fuerte o temporal","walking":"Fácil — ascensores en las estaciones y miradores llanos","admission":"Teleférico no incluido: 17.000 KRW ida y vuelta por adulto, 25.000 KRW la cabina Crystal, pago in situ. El parque Amnam en sí es gratuito."},"image":"/images/tours/songdo-beach/chatgpt-image-2026-5-10-12-32-12.webp","images":["/images/tours/songdo-beach/chatgpt-image-2026-5-10-12-32-12.webp","/images/tours/songdo-beach/songdo-beach-sign-couple.webp"]},{"name":"Parque Yongdusan y Torre de Busan","time":"≈ 16:25","number":11,"category":"Mirador de la Ciudad","duration":"20 min","timeUsed":["Bajada del autobús cerca de la Calle de Moda Gwangbok-ro (~5 min)","Subida en escalera mecánica a la plaza del parque (~5 min)","Reloj floral + estatua del Almirante Yi Sun-sin + fotos de la Campana Ciudadana (~10 min)","Exterior del observatorio de la torre + vista panorámica 360° del parque (entrada no incluida) (~10 min)"],"_poi_meta":{"poi_key":"yongdusan_park","kb_version":"1.25","verified_date":"2026-04-29","sources":["Visit Busan official","Wikipedia","Busan Diamond Tower official (busandiamondtower.co.kr)","Korea Tourism Organization","Busan Metropolitan City heritage records"]},"highlights":["**''Montaña Cabeza de Dragón''** — barrera protectora histórica contra los wokou (piratas japoneses)","Emplazamiento del **waegwan de la era Joseon (enclave comercial japonés 1678–1878)** + **Santuario Ryūtōsan** + barriada de la Guerra de Corea","**Torre de Busan 1973** → rebautizada **Torre Diamante de Busan 2021** tras la remodelación","**Cima de la torre modelada según el baldaquino de la Pagoda Dabotap de Bulguksa** (TN 20, Gyeongju) — cita del patrimonio Silla","**Estatua del Almirante Yi Sun-sin** (1545–1598) — héroe de la Guerra Imjin con los barcos tortuga que nunca perdió un barco","**Campana de los Ciudadanos** — 100,000 donantes; repicada 33× en Nochevieja + 1 de marzo","Observatorio de la torre ₩12,000 adulto; parque gratuito las 24h","**Escalera mecánica cubierta desde Gwangbok-ro** — sin escalera mecánica de regreso","**Ritual de los 33 toques de la Campana de los Ciudadanos** — repicada **33 veces en Nochevieja y el 1 de marzo (Día del Movimiento de Independencia)** — los **33 toques conmemoran a los 33 firmantes coreanos de la Declaración de Independencia de 1919** leída en el Parque Tapgol en Seúl; vincula la identidad cívica de Busan con la narrativa de la independencia nacional"],"smartNotes":{"photo":"Desde el observatorio de Busan Diamond Tower a 120 m (189 m de elevación total en la cima) — panorama de 360° al Puerto de Busan, el Puente Yeongdo y Tsushima en días despejados. Cúspide de la torre inspirada en el baldaquino del Bulguksa Dabotap (NT 20) en Gyeongju. Mejor al atardecer y después del anochecer.","tip":"Combine la visita a la torre con la **estatua del Almirante Yi Sun-sin** (héroe de la Guerra Imjin con los barcos tortuga que nunca perdió un barco) y la **Campana de los Ciudadanos** (repicada **33 veces en Nochevieja y el 1 de marzo**, en conmemoración de los 33 firmantes de la Declaración de Independencia de 1919)."},"whyOnRoute":"Yongdusan ofrece la panorámica de 360 grados más reconocible de Busan y cierra el circuito a pie: el parque está justo encima de las calles de Nampo-dong que el grupo recorrió antes, así que la última parada replantea el día desde arriba antes del corto trayecto de vuelta al barco.","convenience":{"restroom":"En la plaza del parque y dentro de Busan Diamond Tower","parking":"Sin estacionamiento en el lugar — utilizar los aparcamientos públicos de Nampo-dong y subir por la escalera mecánica"},"description":"**El Parque Yongdusan (용두산공원, ''Parque de la Montaña Cabeza de Dragón'')** — un parque cívico de **69.000 m²** en el corazón de Nampo-dong con **70 especies de árboles** — es un lugar histórico de múltiples capas: fue en su día un **waegwan de la era Joseon** (Choryang Wakan, el **enclave comercial y diplomático japonés de 1678 a 1878**), luego un **Santuario Ryūtōsan japonés (siglos XVII–principios del XX)**, después una **barriada de refugiados de la Guerra de Corea** (en su mayoría destruida por los incendios de la década de 1950) y, finalmente, reconvertido en el parque moderno actual. \n\nLa **Torre de Busan de 120 metros de altura** (originalmente **inaugurada en 1973**, **rebautizada como ''Torre Diamante de Busan'' tras la remodelación de 2021**) es el punto central del parque — la **parte superior de su mirador está modelada según el baldaquino (dosel) de la Pagoda Dabotap (TN 20) en el Templo Bulguksa de Gyeongju**, una cita arquitectónica explícita que vincula el monumento moderno de Busan con el patrimonio Silla. \n\nLa torre se eleva a **69 m sobre el nivel del mar + 120 m de altura = 189 m de elevación total**, ofreciendo **panorámicas de 360°** hacia el Puerto de Busan, el Puente Yeongdo, la Isla de Tsushima (en días despejados) y el Mercado Jagalchi a sus pies. Otros monumentos del parque: la **estatua de bronce del Almirante Yi Sun-sin (1545–1598)** (el héroe naval oriundo de Busan que derrotó a las fuerzas japonesas en la Guerra Imjin de 1592–1598, famoso por **no haber perdido ni un solo barco**), la **Campana de los Ciudadanos** donada por **100.000 ciudadanos de Busan** (repicada **33 veces en Nochevieja y el 1 de marzo, Día del Movimiento de Independencia**), el **reloj floral** en la entrada y una **escultura de dragón de bronce** simbólica del nombre de la montaña. \n\nEl acceso es a través de una **escalera mecánica cubierta desde la Calle de Moda Gwangbok-ro** (sin escalera mecánica de regreso — se desciende por escaleras). \n\n**Parque gratuito las 24 h**; **mirador de la Torre Diamante de Busan ₩12.000 adultos / ₩9.000 mayores de 65 años o niños de 3–12 años, horario 10:00–22:00 (última entrada 21:30)**.","visitBasics":{"hours":"Parque abierto 24h; observatorio de Busan Diamond Tower 10:00–22:00 (última admisión 21:30)","closed":"Torre abierta todo el año (cierres ocasionales por seguridad en caso de vientos extremos)","admission":"Parque GRATIS; Busan Diamond Tower ₩12,000 adulto / ₩9,000 tercera edad 65+ o niño 3–12","walking":"Escalera mecánica cubierta desde Gwangbok-ro Fashion Street para el ascenso (sin escalera mecánica de regreso — descender por escaleras)"},"image":"/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","images":["/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","/images/tours/busan-tower/kakaotalk-20260510-222952680.webp","/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp","/images/tours/busan-tower/busan-tower-heart-sign-family.webp","/images/tours/busan-tower/busan-tower-yongdusan-pavilion-day.webp"],"imageCredits":[{"url":"/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","source":"atoc-korea"},{"url":"/images/tours/busan-tower/kakaotalk-20260510-222952680.webp","source":"atoc-korea"},{"url":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp","source":"atoc-korea"},{"url":"/images/tours/busan-tower/busan-tower-heart-sign-family.webp","source":"atoc-korea"},{"url":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-day.webp","source":"atoc-korea"},{"url":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","location":"Parque Yongdusan y Torre de Busan","caption":"Parque Yongdusan y Torre de Busan — photo 1","alt":"Parque Yongdusan y Torre de Busan — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/busan-tower/kakaotalk-20260510-222952680.webp","location":"Parque Yongdusan y Torre de Busan","caption":"Parque Yongdusan y Torre de Busan — photo 2","alt":"Parque Yongdusan y Torre de Busan — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp","location":"Parque Yongdusan y Torre de Busan","caption":"Parque Yongdusan y Torre de Busan — photo 3","alt":"Parque Yongdusan y Torre de Busan — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/busan-tower/busan-tower-heart-sign-family.webp","location":"Parque Yongdusan y Torre de Busan","caption":"Parque Yongdusan y Torre de Busan — photo 7","alt":"Parque Yongdusan y Torre de Busan — gallery image 7"},{"id":5,"type":"photo","src":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-day.webp","location":"Parque Yongdusan y Torre de Busan","caption":"Parque Yongdusan y Torre de Busan — photo 8","alt":"Parque Yongdusan y Torre de Busan — gallery image 8"}]},{"number":12,"time":"≈ 17:00","duration":"15 min en vehículo","name":"Regreso al Puerto de Busan","category":"Regreso","description":"El vehículo sale del punto de recogida de Yongdusan / Gwangbok-ro sobre las **16:45** y cruza el centro de Busan de vuelta a **la misma terminal en la que te recogimos**, con llegada hacia las **17:00**: unas **8 horas** después de la recogida.\n\nEso deja un margen holgado frente a los all-aboard habituales de las escalas de crucero en Busan. Si tu barco zarpa inusualmente pronto, díselo al guía en la recogida de la mañana: el orden del día se ajusta sobre la marcha, normalmente recortando las paradas de Songdo y Yongdusan.","highlights":["Regreso directo del grupo a la terminal de cruceros original","**Margen de 60–90 min antes del embarque**","**Sin traslados individuales al hotel** (horario fijo para grupos pequeños)"],"whyOnRoute":"La vuelta a la terminal de cruceros es la restricción dura del día. Dejarte hacia las 17:00 — ocho horas después de la recogida — deja un margen real frente a los all-aboard habituales de las escalas en Busan, y el guía ajusta el orden sobre la marcha si tu barco zarpa inusualmente pronto.","_poi_meta":{"poi_key":"OPS_busan_port_return","kb_version":"1.15","verified_date":"2026-04-29"},"image":null,"_role":"dropoff"}],"routeFlowStops":[{"name":"Recogida en el Puerto de Busan (sala de llegadas de la terminal de cruceros)","type":"origin","theme":"Salida"},{"name":"Templo Haedong Yonggungsa","type":"primary","theme":"Templo Budista / Costero"},{"name":"Cementerio Memorial de la ONU en Corea","type":"primary","theme":"Memorial / Historia de Guerra"},{"name":"Almuerzo en un restaurante local de Busan (por tu cuenta)","type":"meal","theme":"Comida"},{"name":"Mercado de Pescado Jagalchi","type":"primary","theme":"Mercado de Pescado / Cultura Local"},{"name":"Plaza BIFF","type":"primary","theme":"Distrito del Cine / Comida callejera"},{"name":"Mercado Gukje","type":"primary","theme":"Mercado Tradicional / Patrimonio de la Guerra de Corea"},{"name":"Pueblo Cultural de Gamcheon","type":"primary","theme":"Pueblo de arte"},{"name":"Pasarela Songdo Cloud Trails","type":"primary","theme":"Pasarela sobre el mar"},{"name":"Songdo Sky Park (parque Amnam)","type":"primary","theme":"Parque del cabo / teleférico opcional"},{"name":"Parque Yongdusan y Torre de Busan","type":"primary","theme":"Mirador de la Ciudad"},{"name":"Regreso al Puerto de Busan","type":"return","theme":"Regreso"}],"routePhases":[{"phase":"De la terminal a la costa","duration":"≈ 1 h 35 min","description":"Recogida en la terminal de cruceros a las 09:00 con margen para el desembarque, y después hacia el noreste por la costa hasta Haedong Yonggungsa, con llegada a las 09:45, por delante de la avalancha de autocares que se forma a media mañana."},{"phase":"Cementerio y almuerzo","duration":"≈ 1 h 40 min","description":"Cementerio Conmemorativo de la ONU (30 min) para situar la Guerra de Corea, y luego un almuerzo bien de Busan — dwaeji-gukbap o milmyeon — por tu cuenta."},{"phase":"Nampo-dong a pie","duration":"≈ 1 h 25 min","description":"El mercado de Jagalchi, la plaza BIFF y el mercado Gukje son tres paradas distintas separadas por unos 600 m, así que el centro del día se recorre andando y no en vehículo."},{"phase":"La ladera de Gamcheon","duration":"≈ 1 h 5 min","description":"Aldea Cultural de Gamcheon (45 min) para la panorámica de casas pintadas, a un traslado corto de Nampo-dong."},{"phase":"Songdo y la vuelta","duration":"≈ 1 h 35 min","description":"La pasarela Songdo Cloud Trails, después el Sky Park al otro lado de la bahía si eliges el teleférico, y el parque Yongdusan antes de volver: en la terminal a las 17:00, y siempre ajustado al all-aboard de tu barco."}],"routeShapeIntro":{"title":"Cómo transcurre este día","subtitle":"Recogida en la terminal de cruceros a las 09:00 y, mientras el acantilado sigue tranquilo, primero al noreste hasta Haedong Yonggungsa. Después se cruza la ciudad hacia el Cementerio Conmemorativo de la ONU y el almuerzo por tu cuenta; a continuación Nampo-dong recorrido a pie como tres paradas distintas (mercado de Jagalchi, plaza BIFF, mercado Gukje); la ladera pintada de Gamcheon; Songdo para la pasarela Cloud Trails y, si tomas el teleférico, el Sky Park al otro lado de la bahía; el parque Yongdusan al final, y de vuelta en tu terminal a las 17:00."},"whyTourWorks":{"bestFor":["Pasajeros de crucero con escala en Busan de 8 horas o más","Visitantes por primera vez que desean un recorrido completo por Busan en un solo día","Parejas y familias adultas","Viajeros que priorizan costa + cultura + mercado en una sola ruta"],"lessIdealFor":["Viajeros que desean caminar lo mínimo posible","Viajeros con movilidad reducida (ladera de Gamcheon)","Grupos con carriolas/cochecitos de bebé","Pasajeros de crucero con escala en puerto menor a ≈8 horas"],"routeLogicSections":[{"title":"Por qué esta ruta está diseñada de esta manera","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Las cinco experiencias emblemáticas de Busan, con margen de tiempo para el regreso","detail":"Muchos tours de día en crucero omiten el Cementerio de la ONU (demasiado solemne para un día de playa) o Gamcheon (demasiado lejos del puerto). Esta ruta incluye ambos, además de Taejongdae, Yongdusan/Torre de Busan y Jagalchi/Nampo-dong, y aun así deja un margen de seguridad de 60 minutos para el trayecto de regreso. La ventana de 8 horas está calculada en función del tráfico real de Busan, no de un horario ideal de folleto turístico."},{"label":"Diseñado para el horario del crucero, no para el reloj del operador","detail":"La recogida está calibrada según la llegada real de su barco, no con un horario fijo. Los barcos que arriban antes de las 07:00 activan una opción madrugadora (recargo de ₩10,000/persona) para que no pierda tiempo en la terminal. La hora de regreso está programada para dejar al menos 60 minutos de margen antes de la hora de embarque indicada."},{"label":"Guía bilingüe certificado, sin desvíos a tiendas","detail":"Los guías están licenciados por la Organización de Turismo de Corea y tienen fluidez en inglés y chino. No hay tiendas de ginseng, paradas en duty-free ni desvíos a recuerdos con comisión: cada minuto del día se dedica a las atracciones o al traslado. Esto es más inusual de lo que parece en los tours grupales de crucero."},{"label":"Precio de furgoneta compartida, entre el autocar y el tour privado","detail":"Las excursiones privadas de crucero en Busan cuestan entre $300 y $500+ por grupo. Los tours en autocar llevan más de 40 pasajeros a un precio bajo por persona. Esta versión en furgoneta compartida se sitúa en el término medio, con hasta 12 pasajeros por salida — accesible para cruceristas en solitario, parejas y grupos pequeños que no necesitan un vehículo privado. Desventaja: circuito fijo, no personalizable."}]}]},"practicalAccordionItems":[{"id":"inclusions","title":"Qué está incluido","preview":"Incluye: Entradas de las paradas del itinerario · Guía en inglés y chino · Traslado de ida y vuelta desde tu terminal de cruceros · Peajes, aparcamiento y combustible · Gastos de gestión de la reserva","content":["Incluye: Entradas de las paradas del itinerario · Guía en inglés y chino · Traslado de ida y vuelta desde tu terminal de cruceros · Peajes, aparcamiento y combustible · Gastos de gestión de la reserva","No incluye: Comidas y bebidas · Gastos personales · Propinas · Seguro de viaje · Mirador de la Busan Diamond Tower (elección in situ) · Sky Capsule y tren de la playa de Haeundae (elección in situ) · Teleférico marino de Songdo (elección in situ)"]},{"id":"pickup","title":"Recogida y regreso","preview":"El grupo se reúne en la sala de llegadas de la terminal de cruceros de Busan en la que atraque tu barco: la Terminal Internacional de Cruceros de Busan (Yeongdo) o la Terminal Internacional de Pasajeros del Puerto de Busan (Choryang). La terminal se confirma al reservar.","content":["El grupo se reúne en la sala de llegadas de la terminal de cruceros de Busan en la que atraque tu barco: la Terminal Internacional de Cruceros de Busan (Yeongdo) o la Terminal Internacional de Pasajeros del Puerto de Busan (Choryang). La terminal se confirma al reservar.","La hora de recogida está calibrada según el desembarco real de su barco, no con un horario fijo.","Proporcione el nombre del barco, la fecha de escala, la hora prevista de desembarco y la hora límite de embarque al momento de reservar.","La recogida temprana (antes de las 08:00) añade ₩10,000 por persona."]},{"id":"sailaway","title":"Horario de salida del barco","preview":"Regreso a la terminal de cruceros al menos 60 minutos antes de su hora límite de embarque.","content":["Regreso a la terminal de cruceros al menos 60 minutos antes de su hora límite de embarque.","Regla general en cruceros: regrese al barco al menos 30 minutos antes de la hora de salida indicada.","El guía lleva un seguimiento del horario individual de cada pasajero y prioriza el orden de regreso si varios barcos zarpan a diferentes horas.","La ruta se planifica con un margen de 60 minutos para el tráfico de regreso."]},{"id":"walking","title":"Caminata y terreno","preview":"Moderado.","content":["Moderado.","El pueblo de Gamcheon tiene callejones y escaleras empinadas (construido en una ladera) — no es accesible para sillas de ruedas y es difícil para cochecitos de bebé.","El circuito completo por los acantilados de Taejongdae es de 4,3 km, pero el Tren Danubi opcional (₩4.000) permite evitar la subida.","El Cementerio de la ONU y Yongdusan son llanos.","Caminata total: ≈3–5 km según las opciones elegidas en Taejongdae/Gamcheon.","Es imprescindible usar calzado cómodo con punta cerrada."]},{"id":"cancellation","title":"Cancelación","preview":"Cancelación gratuita hasta 24 horas antes de la recogida.","content":["Cancelación gratuita hasta 24 horas antes de la recogida.","Las cancelaciones el mismo día y las ausencias no son reembolsables.","Si la escala en puerto de su barco es cancelada por la naviera, se realizará un reembolso completo con la documentación de cancelación correspondiente."]},{"id":"accessibility","title":"Niños y accesibilidad","preview":"Los niños a partir de 8 años son bienvenidos y la ruta es adecuada para ellos — el Tren Danubi de Taejongdae…","content":["Los niños a partir de 8 años son bienvenidos y la ruta es adecuada para ellos — el Tren Danubi de Taejongdae es el favorito de los más pequeños, y los peces vivos del mercado Jagalchi siempre resultan fascinantes.","Los cochecitos de bebé no son viables en Gamcheon (hay escaleras); el resto de las paradas sí los admiten.","Los usuarios de silla de ruedas deberían considerar un tour privado de crucero con ajustes de ruta — Gamcheon y el sendero por los acantilados de Taejongdae son los principales obstáculos."]},{"id":"policy-surcharge-cancellation","title":"Suplementos, cancelación y a quién se vende esta excursión","preview":"Recogida antes de las 08:00 o final después de las 20:00: 10.000 KRW por persona. Cancelación gratuita hasta 24 horas antes. A partir de 4 años. Solo pasajeros de crucero.","content":["Suplemento fuera de horario: si tu barco obliga a recogerte antes de las 08:00, o la excursión termina después de las 20:00, se aplica un suplemento de 10.000 KRW por persona que se paga el mismo día.","Cancelación: gratuita hasta 24 horas antes del inicio. Dentro de esas 24 horas la reserva no es reembolsable.","Edad mínima: los pasajeros deben tener 4 años o más.","Solo pasajeros de crucero: esta excursión se vende a quienes llegan en un crucero que hace escala en Busan. Las reservas de viajeros sin escala en Busan se rechazan y se reembolsan.","Hora de vuelta: el día se organiza en torno al all-aboard de tu barco y la vuelta se programa por delante de esa hora."]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"Ver notas estacionales"},"tomorrow":{"temp":"—","label":"Ver notas estacionales"},"_seasonalSummary":"Busan is South Korea''s southernmost major city — milder and wetter than Seoul, with mild winters (5–10 °C lows). Summer is humid, with peak rainfall in July monsoon.","_seasonalTemperatures":[{"season":"Spring (Mar–May)","range":"8–22 °C","notes":"Cherry blossoms in late March / early April."},{"season":"Summer (Jun–Aug)","range":"22–30 °C","notes":"Hot and humid; July monsoon possible. Sea breeze keeps Taejongdae mild."},{"season":"Autumn (Sep–Nov)","range":"10–24 °C","notes":"Best season — clearest air, warmest sea. Foliage in late October."},{"season":"Winter (Dec–Feb)","range":"0–10 °C","notes":"Mild for Korea but can be windy at coastal stops."}]},"seasonalVariations":[{"season":"Primavera (mar–may)","description":"Flor de cerezo en el parque Yongdusan y a lo largo de la carretera costera de Taejongdae a finales de marzo / principios de abril. La mejor temporada para las escalas de cruceros."},{"season":"Verano (jun–ago)","description":"Días largos; la Busan costera es más fresca que el interior de Corea gracias a la brisa marina. En julio puede haber lluvias monzónicas — consulte el pronóstico del tiempo."},{"season":"Otoño (sep–nov)","description":"Mayor visibilidad para las vistas de Tsushima desde Taejongdae; follaje a finales de octubre. La mejor temporada en general."},{"season":"Invierno (dic.–feb.)","description":"Menos aglomeraciones; vistas despejadas al mar; clima suave en comparación con Seúl (mínimas invernales en Busan: 5–10 °C)."}],"bookingTrustItems":[{"icon":"check-circle","title":"Operador local con licencia","description":"Operador turístico coreano autorizado con seguro completo","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600"},{"icon":"route","title":"Especialistas en rutas","description":"Itinerario personalizado, no un circuito genérico","iconBg":"bg-sky-50/80","iconColor":"text-sky-600"},{"icon":"users","title":"Tamaño de grupo seleccionado","description":"Dimensionado adecuadamente para la ruta","iconBg":"bg-amber-50/80","iconColor":"text-amber-600"}],"bookingSupportSteps":[{"timing":"Inmediatamente","title":"Confirmación instantánea","detail":"Confirmación de reserva con resumen del itinerario"},{"timing":"12 horas antes","title":"Recordatorio de 12 horas","detail":"Actualización meteorológica y posibles ajustes de ruta"},{"timing":"La noche anterior","title":"Información final de recogida","detail":"Hora exacta de recogida y contacto del conductor"},{"timing":"Mañana del tour","title":"Notas de ruta del día","detail":"Informe matutino basado en condiciones en tiempo real"},{"timing":"Durante el tour","title":"Consejos parada por parada","detail":"Orientación en tiempo real en cada lugar"},{"timing":"Tras el tour","title":"Asistencia posvuelta","detail":"Seguimiento y recomendaciones"}],"staticQuestions":[{"id":"q-cruise-busy-day","question":"¿Se llenará el tour en los días de mayor afluencia de cruceros?","answer":"La furgoneta compartida tiene capacidad para aproximadamentehasta 12 pasajeros. En los días pico de cruceros, el operador pone en marcha varias furgonetas de forma simultánea en lugar de sobrecargar una sola — la dinámica de grupo es parte del formato y, por lo general, compartirás el viaje con cruceristas de varios barcos diferentes."},{"id":"q-early-arrival","question":"¿Y si mi barco llega muy temprano? ¿Puedo unirme igualmente?","answer":"Sí. La recogida anticipada (antes de las 08:00) está disponible con un suplemento de ₩10,000 por persona. Resulta útil para cruceros con llegadas entre las 06:00 y las 07:00, donde el horario estándar de inicio a las 09:00 te dejaría esperando dos horas en la terminal."},{"id":"q-lunch","question":"¿Está incluido el almuerzo?","answer":"No. El almuerzo es tiempo libre en un restaurante local de Busan recomendado por el guía; calcula un presupuesto de ₩10,000–₩20,000 por persona. Las opciones más habituales son el dwaeji-gukbap (sopa de cerdo con arroz al estilo de Busan), el milmyeon (fideos fríos de trigo) o un set de bibimbap. El guía puede orientarte hacia restaurantes vegetarianos, halal o sin gluten si lo indicas con antelación al reservar."},{"id":"q-vs-private-cruise","question":"¿En qué se diferencia esto de un tour privado en crucero por Busan?","answer":"Los tours privados de crucero se realizan exclusivamente para tu grupo, con un itinerario personalizable y recogida en la puerta del barco, con un coste típico de $90–$120+ por persona (o $300–$500+ por grupo). Esta versión en furgoneta compartida opera a $68.95 por persona en un circuito fijo. Elige esta opción por el precio; elige la privada si buscas flexibilidad, accesibilidad o quieres omitir las paradas estándar."},{"id":"q-gamcheon-stairs","question":"¿Qué pasa si las escaleras de Gamcheon son demasiado?","answer":"Las principales zonas fotográficas de Gamcheon son accesibles con un corto paseo desde la parada del autobús — solo la exploración más profunda requiere las escaleras empinadas. El guía puede llevarte por la sección superior accesible del pueblo. Si la movilidad es una preocupación, indícalo al reservar; para total accesibilidad, un tour privado con ajustes de ruta es la mejor opción."},{"id":"q-customize","question":"¿Puedo personalizar el itinerario?","answer":"De forma limitada — este es un producto compartido con ruta fija. El guía puede ajustar los tiempos dentro del recorrido (pasar más tiempo en Gamcheon, menos en Yongdusan, etc.), pero no puede cambiar ni eliminar paradas. Para una personalización completa, el tour privado de crucero por Busan es la elección correcta."},{"id":"q-tower-tickets","question":"¿Está incluida la entrada al mirador de la Torre de Busan?","answer":"No — el mirador es opcional (₩12,000 adultos, ₩9,000 jóvenes). El parque Yongdusan en sí es gratuito y ofrece una excelente vista de la ciudad a nivel del suelo. La mayoría de los grupos omite el mirador debido al tiempo que consume en relación con el tiempo disponible; si deseas subir, avisa al guía a la llegada para que lo incorpore en el tiempo de parada."},{"id":"q-taejongdae-train","question":"¿Deberíamos tomar el Tren Danubi en Taejongdae?","answer":"Si tienes alguna preocupación respecto al recorrido de 4,3 km por los acantilados, sí — el Tren Danubi (₩4,000 adultos) recorre el circuito en aproximadamente 30 minutos con paradas en el faro y el mirador del acantilado, y resuelve el desnivel del inicio. Los caminantes activos pueden hacer el sendero en 60–75 minutos. El tiempo de parada de 75 minutos se adapta a cualquiera de las dos opciones."},{"id":"q-jagalchi-eat","question":"¿Podemos comer en Jagalchi en lugar de en el restaurante del almuerzo?","answer":"El recorrido llega a Jagalchi a las 16:00 — pasado el almuerzo y antes de la cena — por lo que comer allí significa aperitivos callejeros, hwe (pescado crudo en lonchas de un puesto) o simplemente curiosear. Si tu prioridad es una comida de marisco en Jagalchi, indícalo al reservar; el guía puede mover el horario del almuerzo, aunque el ritmo del tour asume el descanso habitual en el restaurante de mediodía."},{"id":"first-time","question":"¿Es una buena opción para quienes visitan Busan por primera vez?","answer":"Sí — cubre las paradas más representativas de Busan en un único día equilibrado, con una combinación de memorial, costa, pueblo artístico, mirador y mercado. Los visitantes por primera vez con un solo día de escala en el puerto son el público principal de este producto."},{"id":"walking","question":"¿Cuánto hay que caminar?","answer":"Aproximadamente 3–5 km según las elecciones que se hagan. Los callejones en ladera de Gamcheon y el sendero del acantilado de Taejongdae son los tramos más activos; el Cementerio de la ONU y Yongdusan son llanos. El Tren Danubi en Taejongdae es una opción para evitar el desnivel. Es imprescindible llevar calzado cerrado y cómodo."},{"id":"family","question":"¿Es adecuado para familias con niños?","answer":"Sí para niños en edad escolar (aproximadamente 8 años en adelante) que puedan con las escaleras de Gamcheon. Los niños suelen responder mejor al Tren Danubi en Taejongdae y al suelo de peces vivos en Jagalchi. El Cementerio de la ONU es corto y tranquilo."},{"id":"seniors","question":"¿Pueden participar adultos mayores cómodamente?","answer":"Los mayores activos no tendrán problema; el Tren Danubi resuelve Taejongdae y la sección superior de Gamcheon es mayoritariamente transitable. Los viajeros con limitaciones de movilidad significativas deberían considerar un tour privado de crucero en su lugar — la ladera de Gamcheon es el principal obstáculo."},{"id":"children","question":"¿Cuál es la edad mínima recomendada?","answer":"Lo más adecuado es a partir de unos 8 años. Los niños menores de esa edad pueden tener dificultades con las escaleras de Gamcheon y el ritmo del día completo. Si traes niños más pequeños, indícalo al reservar para que el guía pueda planificar en consecuencia."},{"id":"weather","question":"¿Qué ocurre si hay lluvias intensas o un tifón?","answer":"Lluvia ligera: el tour opera según lo previsto. Lluvia intensa: el sendero del acantilado de Taejongdae cierra; el Tren Danubi sigue funcionando. Gamcheon permanece abierto, aunque con posibilidades limitadas para fotografiar. Si se emite una alerta de tifón, el operador ofrece la posibilidad de cambiar la reserva o un reembolso completo. Si la naviera cancela tu escala en el puerto, reembolso completo con documentación."}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"Selecciona la fecha y el tamaño de tu grupo para comprobar la disponibilidad en tiempo real y completar tu reserva.","price":{"amountLabel":"68.95","currency":"USD","per":"person","salePriceUsd":68.95}},"matching_profile":{"profile_version":6,"is_active":true,"product_id":"busan-small-group-sightseeing-tour-cruise-passengers","product_type":"small_group","route_type":"fixed_route","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"minicoach","duration_hours":8,"region_tags":["busan_haeundae","busan_jung_gu","busan_saha_gu"],"theme_tags":["cruise_excursion","buddhist_temple","coast","art_village","market"],"poi_tags":["gamcheon_culture_village","jagalchi_market","taejongdae","un_memorial_cemetery","yongdusan_park"],"pace_level":0.8,"walking_level":0.8,"scenic_level":1,"photo_level":1,"culture_level":0.8,"relax_level":0.6,"first_time_fit":1,"family_fit":0.6,"senior_fit":0.4,"couple_fit":1,"solo_traveler_fit":1,"active_traveler_fit":0.8,"adult_family_fit":0.8,"family_with_teens_fit":1,"young_kids_fit":0.8,"senior_active_fit":0.6,"senior_general_fit":0.4,"mobility_friendly_fit":0.4,"stroller_fit":0.2,"one_day_fit":1,"same_day_flight_fit":0.2,"rain_fit":0.6,"value_for_money_fit":1,"iconic_landmark_fit":1,"cafe_fit":0.8,"food_fit":1,"nature_fit":0.6,"beach_fit":0.4,"nightlife_fit":0.2,"shopping_fit":0.6,"no_shopping_fit":0.6,"local_culture_fit":0.8,"storytelling_fit":1,"unesco_fit":0.2,"intangible_heritage_fit":0.2,"indoor_ratio":0.15,"weather_sensitivity":0.7,"comfort_level":0.8,"budget_fit":0.85,"premium_fit":0.1,"small_group_fit":1,"private_fit":0.2,"bus_fit":1,"price_band":"mid","pickup_base":"busan_cruise_terminal","return_time_band":"16:30-17:00","duration_band":"8h","min_recommended_age":8,"hard_constraints":{"avoidIf":["tight_same_day_depa