  detail_payload = '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"busan-private-car-charter-cruise-shore","locale":"ja","product_id":"busan-private-car-charter-cruise-shore","seo":{"pageTitle":"釜山クルーズ寄港地観光 プライベートカーチャーター（8時間）| AtoC Korea","metaDescription":"クルーズ乗客向けの完全カスタマイズ可能な釜山プライベートカーチャーター（8時間）。英語対応ドライバー、時間厳守の帰港保証、ホテル／KTX駅／クルーズ港からの送迎付き。","ogImage":"https://www.atockorea.com/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","primaryKeywords":["釜山プライベートカーチャーター","釜山クルーズ寄港地観光","釜山クルーズ プライベートデイツアー","釜山 英語対応ドライバー","釜山プライベートツアー（8時間）"],"title":"釜山プライベートカーチャーター・クルーズ寄港地観光・8時間カスタマイズ可能"},"catalog_card":{"slug":"busan-private-car-charter-cruise-shore","title":"釜山クルーズ寄港地・プライベートカー","subtitle":"公認英語対応ドライバーガイドとエアコン完備のプライベート車両で、あなただけの釜山の一日を—時間厳守の帰港保証付き。","region":"釜山（クルーズ港＋市内中心部）","duration":"8時間","stopsCount":5,"rating":0,"reviewCount":0,"badges":["プライベートツアー","カスタマイズ可能なルート","クルーズターミナル送迎込み"],"heroImage":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","thumbnail":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","priceLabel":"","shortCardDescription":"公認英語対応ドライバーガイド付きの、釜山クルーズ乗客向け8時間プライベートカーチャーター。標準行程はUN記念公園、太宗台、甘川文化村、龍頭山公園、チャガルチ市場をカバー。完全カスタマイズ可能。クルーズターミナル、KTX駅、釜山市内の主要ホテルからの送迎；時間厳守での帰港を保証。","tags":["private_tour","customizable_route","cruise_pickup_included","on_time_return_guaranteed"]},"headlineLine1":"釜山クルーズ寄港地・プライベートカー","headlineLine2":"ツアー","price":{"amountLabel":"456.99","currency":"USD","per":"vehicle","salePriceUsd":456.99},"hero":{"imageUrl":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","imagePosition":"center 50%","tagline":"UN記念公園から太宗台の断崖、甘川の彩り豊かな路地、チャガルチの活気ある港まで—プライベートな8時間、あなたのルートで、あなたのペースで。時間厳守の帰港保証付き。","pills":["プライベート車両","公認ドライバーガイド","時間厳守の帰港保証"],"meta":{"duration":"8時間","region":"釜山（クルーズ港＋市内中心部）","stops":"カスタム","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"概要"},{"id":"itinerary","label":"旅程"},{"id":"details","label":"詳細"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"レビュー"}],"glanceItems":[{"icon":"camera","label":"フォトスポット","value":"良好","level":4},{"icon":"mountain","label":"景観豊か","value":"良好","level":4},{"icon":"footprints","label":"徒歩","value":"普通","level":3},{"icon":"cloud-rain","label":"雨天対応","value":"優秀","level":5},{"icon":"users","label":"ファミリー向け","value":"優秀","level":5},{"icon":"gauge","label":"バランス","value":"柔軟","level":5}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","location":"太宗台の海岸絶壁","alt":"太宗台の海岸絶壁 — gallery image 1","caption":"太宗台の海岸絶壁 — photo 1"},{"id":2,"type":"photo","src":"/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","location":"龍頭山公園＆釜山タワー","alt":"龍頭山公園＆釜山タワー — on-route photo","caption":"龍頭山公園＆釜山タワー"},{"id":3,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"},{"id":4,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-04.webp","location":"太宗台の海岸絶壁","alt":"太宗台の海岸絶壁 — gallery image 2","caption":"太宗台の海岸絶壁 — photo 2"},{"id":5,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-19.webp","location":"太宗台の海岸絶壁","alt":"太宗台の海岸絶壁 — gallery image 3","caption":"太宗台の海岸絶壁 — photo 3"},{"id":6,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-30.webp","location":"太宗台の海岸絶壁","alt":"太宗台の海岸絶壁 — gallery image 4","caption":"太宗台の海岸絶壁 — photo 4"},{"id":7,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-34.webp","location":"太宗台の海岸絶壁","alt":"太宗台の海岸絶壁 — gallery image 5","caption":"太宗台の海岸絶壁 — photo 5"},{"id":8,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-29-06.webp","location":"太宗台の海岸絶壁","alt":"太宗台の海岸絶壁 — gallery image 6","caption":"太宗台の海岸絶壁 — photo 6"},{"id":9,"type":"photo","src":"/images/tours/busan-tower/kakaotalk-20260510-222952680.webp","location":"龍頭山公園＆釜山タワー","alt":"龍頭山公園＆釜山タワー — on-route photo","caption":"龍頭山公園＆釜山タワー"},{"id":10,"type":"photo","src":"/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp","location":"龍頭山公園＆釜山タワー","alt":"龍頭山公園＆釜山タワー — on-route photo","caption":"龍頭山公園＆釜山タワー"},{"id":11,"type":"photo","src":"/images/itinerary/jagalchi-market-interior.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"},{"id":12,"type":"photo","src":"/images/itinerary/jagalchi-night-building.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"},{"id":13,"type":"photo","src":"/images/tours/jagalchi-market/photo-001.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"},{"id":14,"type":"photo","src":"/images/tours/jagalchi-market/photo-002.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"},{"id":15,"type":"photo","src":"/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"},{"id":16,"type":"photo","src":"/images/tours/jagalchi-market/photo-010.webp","location":"南浦洞＆チャガルチ水産市場","alt":"南浦洞＆チャガルチ水産市場 — on-route photo","caption":"南浦洞＆チャガルチ水産市場"}],"itineraryStops":[{"number":1,"time":"Cruise arrival + 30 min","duration":"30分","name":"釜山クルーズターミナル（またはホテル／KTX）でのお出迎え","category":"出発","description":"専属ドライバーが3つのお出迎えポイントのいずれかでお待ちします：**釜山港国際クルーズターミナル**（影島区東三洞、ロイヤル・カリビアンのクァンタム・クラスやプリンセス・クルーズなど釜山港大橋の高さ64mを超える大型船が使用する専用クルーズ埠頭）、**釜山港国際旅客ターミナル**（草梁洞・忠壮大路206番地、**2015年8月31日**開港 — 年間旅客容量**278万人**、5棟合計92,945㎡を誇るアジア第2位（上海に次ぐ）の旅客ターミナル）、またはダウンタウンのホテル／KTX釜山駅。\n\nお出迎えの時刻は**船の公示クリアランス時刻の30分後**に設定されており、入国審査の所要時間のばらつきに対応しています。ドライバーは英語・韓国語の名前プラカードと**印刷されたスケジュールカード**（全停車時間、韓国語の住所（緊急時のタクシー利用に対応）、オペレーターの24時間連絡先を記載）をお持ちします。車両は**お客様のグループ専用のセダンまたはバン**（他のお客様との相乗りなし）— お荷物はツアー中トランクに保管されます。","highlights":["**3つのお出迎えオプション**：クルーズターミナル（影島）、国際旅客ターミナル（草梁）、またはホテル／KTX","**専用車両** — お客様のグループ専用、相乗り不可","ドライバーは名前プラカード＋韓国語・英語スケジュールカードを携帯","お出迎えは船のクリアランス時刻の30分後"],"whyOnRoute":"3つのお出迎えポイントは、釜山の2種類のクルーズターミナル（東三洞の大型クルーズ船専用埠頭と、草梁洞のフェリー・中型クルーズ向け国際旅客ターミナル）に加え、市内ホテルおよびKTX釜山駅をカバーしています。船の到着後30分のバッファーは、3,000人以上の乗客が同時に下船する際に生じる入国審査の遅延に対応するためのものです。","_poi_meta":{"poi_key":"OPS_busan_cruise_pickup","kb_version":"1.15","verified_date":"2026-04-29","sources":["Busan Port Authority","CruiseMapper","NamuWiki"]},"image":null},{"number":2,"time":"≈ 09:30","duration":"60分","name":"国連記念公園（朝鮮戦争）","category":"記念と歴史","description":"**韓国国連記念公園（UNMCK）— 世界で唯一の国連記念墓地** — **1951年1月18日に国連軍司令部により設立**、**1951年4月6日にマシュー・リッジウェイ将軍により捧呈**され、**1959年に国連総会決議に基づき大韓民国から国連に寄贈**されました。この墓地は国連軍の**22の派兵国**（戦闘部隊16カ国＋医療支援6カ国）の戦没者を追悼し、現在**11カ国から2,300基の墓**が維持されています（遺骨の帰国は主に1950年代後半に行われました）。\n\n14ヘクタールの敷地内には、韓国のモダニズム建築家**金重業（1966年）**が設計した**正門**、英語12分間のドキュメンタリーが上映される**記念館**、22の派兵国の国旗が掲揚される**シンボルエリア**、フランク・ゲイロード制作の**米国朝鮮戦争記念碑**（アメリカ戦没者記念事業委員会、2013年）、そして2006年に献呈された**追悼の壁** — 韓国で戦った全国連兵士の名前**40,896名**が**140枚の大理石パネル**に刻まれています。\n\n毎年11月11日午前11時には、**「ターン・トワード・プサン」式典**が墓地と世界22カ国の記念碑で同時に開催されます — 派兵国の全国旗が一斉に降ろされる年に一度の機会です。入場料は**無料**、開園時間は**9:00〜18:00（5月〜9月）／9:00〜17:00（10月〜4月）**で、整備された通路により敷地全体が**車椅子でのアクセスが可能**です。\n\nこの墓地は**国際国連記念公園委員会**が管理し、**1955年12月15日付の国連総会決議977（X）**により国連管轄領土として保護されています。","highlights":["**世界で唯一の国連記念墓地** — 1951年1月18日設立、1959年に韓国から国連に寄贈","**22の派兵国**を追悼、現在**11カ国から2,300基の墓**を維持","**追悼の壁（2006年）** — 140枚の大理石パネルに40,896名の名前を刻銘","韓国人建築家**金重業（1966年）**設計の正門","**「ターン・トワード・プサン」式典** 11月11日午前11時（世界同時開催）","**入場無料**、全面バリアフリー対応","**フランク・ゲイロード米国朝鮮戦争記念碑（2013年、アメリカ戦没者記念事業委員会による献呈）** — ワシントンD.C.のナショナル・モールにある朝鮮戦争退役軍人記念碑「ザ・コラム」（1995年）と同じ彫刻家による作品","**隣接する国連彫刻公園** — 朝鮮戦争に参戦した21カ国の彫刻家から寄贈された34点の彫刻を展示、朝鮮戦争50周年記念として2001年10月24日に開園","**1955年12月15日付の国連総会決議977（X）**により、UNMCKは国際国連記念公園委員会管理下の国連管轄保護領土として正式に設立"],"timeUsed":["シンボルエリア＋22カ国国旗広場（約10分）","記念館＋英語12分間ドキュメンタリー（約15分）","追悼の壁＋遺品展示館（約20分）","黙想の時間＋写真撮影（約10分）","車両まで徒歩で戻る（約5分）"],"whyOnRoute":"UNMCKは**釜山において世界的に最も重要な朝鮮戦争の遺産地**であり、その日の沿岸・文化巡りに対する厳粛な対比をなす。09:30到着でツアーバス団体のピーク時間（約11:00）より前に訪れることができ、60分の滞在時間でドキュメンタリー、追悼の壁、黙想を急かされることなく体験できる。車椅子対応のため当日の停車地の中で最もアクセスしやすい場所であり、意図的に穏やかなオープニングとして設定されている。再乗船時間が限られているクルーズ客にとって、60分の滞在時間は当日最もスケジュールの融通が利く停車地であり、ドキュメンタリー＋象徴エリア＋追悼の壁を約30分に短縮することも、彫刻公園を含む75分に延長することも可能である。","_poi_meta":{"poi_key":"OPS_route_planning","kind":"operational"},"imageCredits":[{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","source":"atoc-korea"},{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-43.webp","source":"atoc-korea"},{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-47.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"在韓国国連記念公園","caption":"在韓国国連記念公園 — 写真 1","alt":"在韓国国連記念公園 — ギャラリー画像 1"},{"id":2,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-43.webp","location":"在韓国国連記念公園","caption":"在韓国国連記念公園 — 写真 2","alt":"在韓国国連記念公園 — ギャラリー画像 2"},{"id":3,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-35-47.webp","location":"在韓国国連記念公園","caption":"在韓国国連記念公園 — 写真 3","alt":"在韓国国連記念公園 — ギャラリー画像 3"}]},{"number":3,"time":"≈ 10:45","duration":"75分","name":"太宗台の海岸絶壁","category":"海岸","description":"**太宗台（태종대）——釜山記念物第28号**（五六島と共同指定）——は、**三国統一**後にここで弓術を練習したと伝えられる**新羅の太宗武烈王（604〜661年、第29代王）**にちなんで命名された**影島最南端に位置する自然公園**である。この場所の代表的な見どころは、影島灯台下に位置する**波食棚「神仙岩」**であり——地質学者はその形成を**第四間氷期（約120,000年前）**と推定し、同心円状の模様や断層帯が見られる堆積岩への長期的な海洋侵食によって形成されたとしている。\n\n断崖上の**影島灯台**は**釜山最古の灯台で1906年建設**（韓国で10番目）、2004年に新塔が追加され——元の灯台は一世紀以上にわたって釜山へ向かう船を導いており、2004年に海洋文化スペース（See & Seaギャラリー＋自然史博物館＋展望台＋カフェ）として改装された。全長4.3kmのループをハイキングするのはきつく、多くの訪問者は**ダヌビ列車**（大人往復約₩4,000、入口広場から出発）を利用し、太院砂利浜→クミョンサ寺院→展望台→影島灯台→太宗寺の順に停車する。\n\n**3階建て展望台**からは、**ティーケトル島（生島）**や——晴れた日には——**日本の対馬島（南東約50km）**まで広がるパノラマビューが楽しめる。この場所には2つの伝説がある：**望夫石**（日本の海賊に連れ去られた夫を待ち続けて石になった貞節な妻の伝説）と、韓国人アーティスト、ジ・スル・ウォン・キョン・リーによる**「限界を超えた光」の彫刻**（青い輪＝海と空、赤＝大地、銀の点＝灯台の光）。\n\n公園内の**太宗寺**では毎年6月下旬〜7月上旬に紫陽花祭りが開催される。公園営業時間：**04:00〜24:00（3月〜10月）／05:00〜24:00（11月〜2月）**、**入場無料**。","highlights":["**釜山記念物第28号**——波食棚は約120,000年前（第四間氷期）に形成","**新羅の太宗武烈王**（604〜661年、三国統一者）にちなんで命名","**影島灯台——釜山最古、1906年建設**（韓国10番目）；2004年改装","**3階建て展望台**から晴れた日には**対馬島（日本、約50km）**まで展望可能","**ダヌビ列車** 往復約₩4,000——4.3km沿岸ループに5停車駅","**望夫石**の伝説＋**「限界を超えた光」の彫刻**（ジ・スル・ウォン・キョン・リー）","公園は無料；トレイルは険しい（灯台エリア＝急な階段が多い）","**釜山国立ジオパーク指定地（2013年）＋国指定文化財名勝第17号（2005年）**——白亜紀の堆積岩断崖、波食棚、球状ホルンフェルス、スランプ構造を保護するデュアル・ヘリテージ指定","太宗寺での**年間アジサイ文化祭**（6月下旬〜7月上旬）には、公園内の西洋アジサイの花のじゅうたんを目当てに10万人以上の来場者が訪れる"],"timeUsed":["観光バスでの乗降＋ダヌビ列車チケット購入（約10分）","列車で展望台へ＋3階パノラマ鑑賞（約20分）","影島灯台まで徒歩＋「限界を超えた光」彫刻鑑賞（約15分）","望夫石＋神仙岩エリアへの断崖沿いの景観（約20分）","列車で入口まで戻る＋集合（約10分）"],"whyOnRoute":"太宗台は**釜山の定番自然景観スポット**であり、後半の都市部・甘川−龍頭山−チャガルチクラスターと理想的なコンビネーションを形成する：当日は厳粛（国連墓地）→雄大な海岸（太宗台）→都市の彩り（甘川）→都市の眺望（龍頭山タワー）→市場（チャガルチ）と移り変わる。75分の時間枠で、険しい4.3kmのフルコースを強いることなく展望台＋灯台ループをカバーでき、ダヌビ列車が高低差のあるルートをアクセスしやすくしている。クルーズ客にとって、75分のダヌビ列車＋展望台＋灯台ループは釜山の雄大な海岸線へ当日最も効率的にアクセスできる手段であり——列車なしでは、このスポットを十分に楽しむために2時間以上が必要になる。","_poi_meta":{"poi_key":"taejongdae","kb_version":"1.25","verified_date":"2026-04-29","sources":["Busan Geopark official","Visit Busan (visitbusan.net)","Wikipedia","Busan Metropolitan City","Yeongdo Lighthouse archive (1906 records)","Busan National Geopark official (busan.go.kr/geopark)"]},"image":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","visitBasics":{"hours":"公園 04:00〜24:00（3月〜10月）/ 05:00〜24:00（11月〜2月）；ダヌビ列車 09:00〜日没","closed":"年中無休（ダヌビ列車は大雨・強風時は運休）","admission":"公園入場無料；**ダヌビ列車 大人往復約₩4,000**、子ども約₩2,000","walking":"全長4.3kmの海岸周回コースは体力を要する；**ダヌビ列車**の停車駅：砂利浜 → 金鰲寺（グミョンサ）→ 展望台 → 影島灯台 → 太宗寺"},"convenience":{"restroom":"入口広場、展望台、影島灯台エリアにあり","parking":"入口広場に大型無料駐車場あり"},"smartNotes":{"photo":"**3階建て展望台**（晴れた日には**南東50kmの対馬（日本）**まで一望）、**影島灯台 — 1906年建設、釜山最古の灯台**、灯台下の波食地形**仙岩テラス（約12万年前、第4間氷期）**。","tip":"体力を要する4.3kmのハイキングは省略して、**ダヌビ列車**で5つの停車駅を巡りましょう。**太宗寺のアジサイ祭り**は6月下旬〜7月上旬に開催されます。灯台エリアは急な階段が多く、ベビーカーには不向きです。"},"images":["/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-04.webp","/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-19.webp","/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-30.webp","/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-34.webp","/images/tours/taejongdae/chatgpt-image-2026-5-10-12-29-06.webp"],"imageCredits":[{"url":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","source":"atoc-korea"},{"url":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-04.webp","source":"atoc-korea"},{"url":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-19.webp","source":"atoc-korea"},{"url":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-30.webp","source":"atoc-korea"},{"url":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-34.webp","source":"atoc-korea"},{"url":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-29-06.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp","location":"太宗台の海岸絶壁","caption":"太宗台の海岸絶壁 — photo 1","alt":"太宗台の海岸絶壁 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-04.webp","location":"太宗台の海岸絶壁","caption":"太宗台の海岸絶壁 — photo 2","alt":"太宗台の海岸絶壁 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-19.webp","location":"太宗台の海岸絶壁","caption":"太宗台の海岸絶壁 — photo 3","alt":"太宗台の海岸絶壁 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-30.webp","location":"太宗台の海岸絶壁","caption":"太宗台の海岸絶壁 — photo 4","alt":"太宗台の海岸絶壁 — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-27-34.webp","location":"太宗台の海岸絶壁","caption":"太宗台の海岸絶壁 — photo 5","alt":"太宗台の海岸絶壁 — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/taejongdae/chatgpt-image-2026-5-10-12-29-06.webp","location":"太宗台の海岸絶壁","caption":"太宗台の海岸絶壁 — photo 6","alt":"太宗台の海岸絶壁 — gallery image 6"}]},{"number":4,"time":"≈ 12:30","duration":"60分","name":"昼食（釜山の地元レストラン）","category":"食事","description":"影島またはナンポドンにあるガイド推薦の**釜山地元レストラン**での昼食 — お客様のご希望に応じて選定します。主なメニューは、**テジクッパ**（西面のテジクッパ通りの老舗で味わえる釜山名物の豚肉とご飯のスープ）、**ミルミョン**（北朝鮮の冷麺（ネンミョン）に対抗する釜山の小麦麺料理、朝鮮戦争避難民の台所で1950年頃に生まれた）、または**フェ**（チャガルチ産の刺身、海鮮がお好みの方に）。\n\n**昼食はツアー料金に含まれていません** — ドライバーが予算に応じてご提案します（目安：₩10,000〜25,000/人）。ベジタリアン・ハラール・アレルギー対応は**事前申告（24時間前推奨）**にて承ります。","highlights":["ドライバーがご一行の希望に応じてご案内（韓国料理 / 海鮮 / インターナショナル）","釜山の代表的なメニュー：**テジクッパ**、**ミルミョン**、**フェ（刺身）**","**昼食はお客様のご負担**（目安：約₩10,000〜25,000/人）","食事制限のリクエストは24時間前の事前申告にて対応"],"whyOnRoute":"12:30の昼食は、太宗台（海岸エリア）と甘川（丘の上エリア）の間に位置しており、1日の流れの中で最も自然な休憩タイミングです。ドライバー推薦の地元レストランは観光地の定番店を上回る質を誇り、朝の送迎時のブリーフィングで推薦に従うか、特定の料理をリクエストすることができます。","_poi_meta":{"poi_key":"OPS_busan_lunch","kb_version":"1.15","verified_date":"2026-04-29"},"visitBasics":{"hours":"レストランによって異なります（通常11:30〜14:30の昼食サービス）","closed":"会場によって異なります；ドライバーが空き状況を確認します","admission":"**現地払い、約₩10,000〜25,000/人**；昼食はツアー料金に**含まれていません**","walking":"最小限 — 車の降車場所から徒歩5分以内のレストラン"},"convenience":{"restroom":"レストラン内","parking":"ドライバーが降車後、最寄りの合法的な待機場所で待機"},"smartNotes":{"photo":"**テジクッパ**（豚肉とご飯のスープ、朝鮮戦争避難民時代から続く釜山の定番料理）または**ミルミョン**（北朝鮮の冷麺に対抗する釜山の小麦麺料理、1950年代の避難民の台所が発祥）は、最も印象的な地元グルメです。","tip":"**ベジタリアン・ハラール・アレルギー対応は24時間前の事前申告が必要**。ドライバーがご一行の希望に応じてご案内（韓国料理 / 海鮮 / インターナショナル）；朝の送迎時に推薦に従うか、特定の料理をリクエストしてください。"}},{"number":5,"time":"≈ 14:00","duration":"75分","name":"甘川文化村","category":"丘の上のアート村","description":"**甘川文化村（감천문화마을）— 釜山の「韓国のマチュ・ピチュ」/「韓国のサントリーニ」** — パステルカラーに彩られた家々が立ち並ぶ丘の上のコミュニティで、**約1万人の住民**が暮らしています。1955年、チョ・チョルジェが創設した**テグクト（太極道）教団の約800世帯（約4,000人）**が朝鮮戦争後にこの地に移住したことで形成されました。\n\nこの村の象徴的な特徴 — **後ろの家の眺めを遮らない屋根の配置**によって生まれる有名な階段状の虹色の景観 — は、**テグクトの「他者の繁栄を妨げない」という哲学**に直接由来しています。2つの政府主導のアートプロジェクトが村を観光地へと変貌させました：**「マチュ・ピチュの夢」（2009年）**と**「ミロミロ」（2010年）**で、どちらも韓国文化体育観光部の委託による壁画、彫刻、インスタレーションが迷路のような路地に点在しています。\n\n村は**2012年にUN-HABITATアジア都市景観賞**を受賞し、現在は**年間約140万人の観光客**が訪れます。主な撮影スポットは、スカイガーデン（ハヌルマル展望台 — 行列はできるが入場無料）の**星の王子さまとキツネのベンチ**、星見台からの**虹色の屋根のパノラマ**、そして9か所のインスタレーションを巡る**スタンプツアーマップ**（約₩2,000）。\n\n**現在も住民が生活しています** — 声を落とし、ドローン禁止、路地でのフラッシュ撮影禁止、ゴミは必ず持ち帰りましょう。営業時間は**09:00〜18:00（3月〜10月）/ 09:00〜17:00（11月〜2月）**、**村の入場は無料**ですが、多くの区間で急な階段や狭い路地があり**ベビーカーや車椅子には不向き** — 滑りにくい靴でお越しください。","highlights":["**1955年テグクト（太極道）避難民集落** — チョ・チョルジェが創設、約800世帯 / 約4,000人","太極道の哲学「他者の繁栄を許す」＝隣人の眺めを遮る屋根を設けない","文化体育観光部アートプロジェクト**「マチュピチュを夢見て」（2009年）**＋**「ミロミロ」（2010年）**","**UN-HABITAT アジア都市景観賞 2012年**","**年間訪問者数 約140万人**","スカイガーデンの**「星の王子さまとキツネのベンチ」**＝定番フォトスポット（長い行列あり・無料）","スタンプツアーマップ ₩2,000（番号付きインスタレーション9か所）","急勾配の路地＋階段＝ベビーカー・車椅子不可","**Kコンテンツの聖地**――「ランニングマン」第126話（チェ・ジウゲスト出演）、『ルカ：ザ・ビギニング』（2021年）、『国際市場で逢いましょう』（2014年）、『小公女』；**韓国観光公社「韓国必訪観光地100選」5年連続選定**"],"timeUsed":["上部入口で観光バス下車（約5分）","星座展望台＋レインボー屋根のパノラマ（約15分）","スカイガーデン＋「星の王子さまとキツネのベンチ」撮影（約20分）","壁画＋クラフトショップを眺めながら迷路路地を下る（約25分）","下部出口に集合（約10分）"],"whyOnRoute":"甘川文化村は**釜山日帰りツアーの視覚的ハイライト**であり、次の目的地・龍頭山と自然にセットになる――どちらも4km離れた丘の上の展望スポットで、一方は住居兼芸術空間、もう一方は市民公園。75分が最適な滞在時間：スカイガーデン＋星の王子さまの行列＋路地の充実した下り歩きには十分な時間でありながら、龍頭山に向かう前に真昼の暑さや急坂で疲弊するほど長くはない。クルーズ観光客にとって、この75分の滞在は一日のメインフォトスポット――スカイガーデン＋星座展望台＋迷路路地の下りは、このルート上の他のどの釜山スポットよりもInstagram映えする。","_poi_meta":{"poi_key":"OPS_busan_cruise_return","kind":"operational"}},{"number":6,"time":"≈ 15:45","duration":"45分","name":"龍頭山公園＆釜山タワー","category":"市内展望スポット","description":"**龍頭山公園（용두산공원・「龍の頭の山公園」）**――南浦洞の中心に位置する**69,000 m²**の市民公園で**70種の樹木**を擁する――は重層的な歴史を持つ場所である：かつては**朝鮮時代の倭館**（草梁倭館、**1678年から1878年まで続いた日本の貿易・外交専用区域**）、次いで日本の**龍頭山神社（17世紀〜20世紀初頭）**、その後**朝鮮戦争期の難民スラム**（1950年代の火災でほとんど消失）を経て、現在の公園として再整備された。\n\n公園の中心をなす**120メートルの釜山タワー**（**1973年開業**、**2021年のリニューアルにより「釜山ダイヤモンドタワー」に改称**）は、その**展望台の頂部が慶州・仏国寺の多宝塔（国宝第20号）の宝蓋（天蓋）をモデルに設計**されており、釜山の現代的ランドマークと新羅の文化遺産を建築的に結びつけている。タワーは**海抜69mの地点に立ち、塔高120m、合計189mの標高**を誇り、釜山港・影島大橋・対馬（晴天時）・チャガルチ市場を望む**360°パノラマ**を提供する。\n\nその他の公園内モニュメント：**李舜臣将軍の銅像（1545〜1598年）**（壬辰倭乱（1592〜1598年）で日本軍を打ち破り、**一度も自軍の船を失わなかった**ことで知られる釜山ゆかりの海軍英雄）、**釜山市民10万人が寄贈した「市民の鐘」**（**大晦日と3月1日の三一節〔独立運動記念日〕に33回打ち鳴らされる**）、入口の**花時計**、そして山の名にちなんだ**龍の銅像**。\n\nアクセスは**光復路ファッションストリートからの屋根付きエスカレーター**を利用（上り専用のため帰りは階段で下山）。**公園は24時間無料開放**；**釜山ダイヤモンドタワー展望台 大人₩12,000／65歳以上シニアまたは3〜12歳こども₩9,000、営業時間 10:00〜22:00（最終入場 21:30）**。","highlights":["**「龍の頭の山」**――歴史的に倭寇（日本の海賊）に対する守護の障壁とされてきた","**朝鮮時代の倭館（日本の貿易専用区域 1678〜1878年）**＋**龍頭山神社**＋朝鮮戦争期のスラム街の跡地","**釜山タワー 1973年開業**→リニューアルを経て**2021年に「釜山ダイヤモンドタワー」に改称**","**塔頂部は仏国寺・多宝塔の宝蓋（天蓋）をモデルに設計**（国宝第20号・慶州）――新羅の文化遺産を引用した建築表現","**李舜臣将軍の像**（1545–1598）— 壬辰倭乱で亀甲船を率い、一隻も失わなかった英雄","**市民の鐘** — 10万人の寄付者；大晦日と3月1日に33回打ち鳴らされる","タワー展望台 大人₩12,000；公園は24時間無料","**光復路からの屋根付きエスカレーター** — 下り用エスカレーターはなし","**市民の鐘・33回打鐘の儀式** — **大晦日と3月1日（独立運動記念日）に33回打ち鳴らされる** — **33回の打鐘は、1919年にソウルのタプコル公園で読み上げられた独立宣言書に署名した33名の韓国人署名者を記念するもの**；釜山の市民としての誇りを国家独立の物語と結びつける"],"timeUsed":["光復路ファッション通りから公園へのエスカレーター（約5分）","花時計 ＋ 李舜臣将軍の像 ＋ 市民の鐘の撮影（約10分）","タワー展望台への登頂 ＋ 360°パノラマ（約25分）","階段での下山（約5分）","市民の鐘パビリオン ＋ 花時計 ＋ 青銅の龍の撮影（約5分）"],"whyOnRoute":"龍頭山では**釜山を代表する360°パノラマ**を夕暮れのゴールデンアワーに堪能できる — タワーが慶州・仏国寺の多宝塔を意匠として取り入れていることから、複数日のクルーズ寄港時に慶州世界遺産巡りと組み合わせるコースとして概念的に繋がっている。45分の滞在枠は公園を歩き回らずに展望台への登頂が完了できるよう設計されており、光復路からのエスカレーターにより急坂の登りを解消している。クルーズ乗客にとって龍頭山は当日の主要な悪天候時の代替スポットとなる — 雨や霧で太宗台の屋外断崖ルートが中止になった場合、ダイヤモンドタワー展望台＋公園が同じ滞在時間内で約75分の屋内代替プランを提供する。","_poi_meta":{"poi_key":"yongdusan_park","kb_version":"1.25","verified_date":"2026-04-29","sources":["Visit Busan official","Wikipedia","Busan Diamond Tower official (busandiamondtower.co.kr)","Korea Tourism Organization","Busan Metropolitan City heritage records"]},"image":"/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","visitBasics":{"hours":"公園は24時間オープン；**釜山ダイヤモンドタワー展望台 10:00〜22:00（最終入場21:30）**","closed":"タワーは年間を通じてオープン（強風時に安全上の理由で臨時閉鎖あり）","admission":"公園入場無料；**釜山ダイヤモンドタワー ₩12,000（大人）/ ₩9,000（65歳以上のシニアまたは3〜12歳の子ども）**","walking":"**光復路ファッション通りからの屋根付きエスカレーター**で登頂（下り用エスカレーターなし — 階段にて下山）"},"convenience":{"restroom":"公園広場内および釜山ダイヤモンドタワー内","parking":"敷地内駐車場なし — 南浦洞の公共駐車場を利用し、エスカレーターで徒歩にて登頂"},"smartNotes":{"photo":"**釜山ダイヤモンドタワー展望台（高さ120m、山頂総標高189m）**から — 晴天時には釜山港・影島大橋・対馬まで望む**360°パノラマ**。タワー頂部は**慶州・仏国寺の多宝塔の天蓋（国宝第20号）を模した設計**。**日没時および夜間**がもっとも美しい。","tip":"タワー訪問は**李舜臣将軍の像**（壬辰倭乱で亀甲船を率い、一隻も失わなかった英雄）と**市民の鐘**（**大晦日と3月1日に33回打ち鳴らされ**、1919年の独立宣言書に署名した33名を記念）とあわせてお楽しみください。"},"images":["/images/tours/busan-tower/chatgpt-image-2026-5-10-12-30-57.webp","/images/tours/busan-tower/kakaotalk-20260510-222952680.webp","/images/tours/busan-tower/busan-tower-yongdusan-pavilion-night.webp"]},{"number":7,"time":"≈ 16:45","duration":"45分","name":"南浦洞＆チャガルチ水産市場","category":"市場＆ストリートフード","description":"**チャガルチ市場（자갈치시장）— 韓国最大の水産市場** — 釜山のダウンタウンのショッピング・グルメ地区**南浦洞**の核心を担う。「チャガルチ」という名前は**「チャガル（砂利）」**に由来し、市場が生まれた砂利浜の海岸を指している。1876年の釜山開港と朝鮮戦争後の復興を経て、**「チャガルチ・アジュンマ」と呼ばれる女性行商人**（戦争未亡人や避難民）たちが、たくましい女性主導の水産経済として市場のアイデンティティを築いた。\n\n現在の**カモメをかたどった近代的な建物**（建築家ヒョンジュン・ミン設計）は**2006年にリニューアルオープン**し、**66,000㎡に約400の業者**が集まる — 1階に生け簀（タコ・アワビ・ナマコ・ヒラメ）、2階に刺身（フェ）レストランがあり、1階で購入した魚を2階でさばいてもらえる（チョコチュジャン（酢コチュジャン）ディップ＋ソジュが定番）。\n\n営業時間は**毎日05:00〜22:00**；**毎月第1・第3火曜日は定休**（訪問前に要確認）。毎年10月開催の**チャガルチ文化観光祭**が最大のイベント。周辺の**南浦洞**には、**BIFFスクエア**（釜山国際映画祭発祥の地、パク・チャヌク、ポン・ジュノら韓国映画スターの手形が歩道に刻まれている）、**国際市場**（朝鮮戦争時代に難民が築いた市場、現在も1,500以上の店舗が営業）、**光復路ファッション通り**がある。\n\n住所：**中区チャガルチ海岸路52番地**。写真撮影のマナー：**生け簀や業者を撮影する際は必ず一声かけること**；チャガルチ・アジュンマはカメラに対して非常に直接的なことで知られている。隣接する生魚の競りは公開市場へ商品を卸す卸売市場で**毎日04:00**から始まる（観光客が見学する場合は事前予約が必要）。","highlights":["**韓国最大の水産市場** — 約400業者 / 66,000㎡","名前の由来 = **「チャガル（砂利）」** ＋ 戦後の女性行商人**「チャガルチ・アジュンマ」**","**2006年にリニューアルオープンした近代的なカモメ型の建物**（建築家ヒョンジュン・ミン設計）","**営業時間 毎日05:00〜22:00**；**第1・第3火曜日定休**","**1階で購入して2階で食べる刺身（フェ）スタイル**","隣接スポット：**BIFFスクエア**（釜山国際映画祭）、**国際市場**、**光復路**","10月開催**チャガルチ文化観光祭**","住所：**中区チャガルチ海岸路52**","**サンナクジ（活きタコの刺し切り）は釜山の食文化を代表する一品** — 小さなタコを生きたまま切り分け、ごま油と塩で提供される；映画『オールド・ボーイ』（2003年）の有名なタコ食いシーンの元となり、この料理を世界に知らしめた"],"timeUsed":["龍頭山から徒歩 / チャガルチ付近での下車（約5分）","1階の生け簀エリアを見学（約15分）","2階の刺し身（フェ）レストランを見学＋南浦洞の街並み撮影（約15分）","軽食・お土産の購入（任意）＋光復路の散策（約10分）","スタンプ押印＋チャガルチのアジュンマ（おばちゃん）屋台でのお土産購入（約5分）"],"whyOnRoute":"チャガルチは**1日観光で最も本物らしい「釜山の味」を体感できる場所**であり、南浦洞のBIFF広場＋国際市場と組み合わせることで、数分前に訪れた龍頭山の高台からの眺めとは対照的な、地に足のついた都市の風景を堪能できます。45分という時間は意図的に短く設定されています——龍頭山の後は、本格的な食事ではなく写真撮影と雰囲気の体験が目的です（食事の時間がクルーズへの再乗船と重なる恐れがあるため）。クルーズ利用客にとって、45分で最も本物らしい「釜山の味」を感じられる絶好の撮影機会です——生け簀＋アジュンマ（おばちゃん）の露店文化＋カモメをモチーフにした屋根の建築を巡り、最後は船の再乗船エリア付近で締めくくります。","_poi_meta":{"poi_key":"jagalchi_market","kb_version":"1.25","verified_date":"2026-04-29","sources":["Visit Busan official","Jagalchi Market Association (jagalchimarket.bisco.or.kr)","Wikipedia","Korea Tourism Organization","Busan Jung-gu official","Busan Tourism Organization (Jagalchi Sannakji designation)"]},"image":"/images/itinerary/jagalchi-harbor-sign.webp","visitBasics":{"hours":"**チャガルチ市場 毎日05:00〜22:00**；活魚競りは04:00開始（観光客向け見学は事前予約が必要）；南浦洞ショッピング街 10:30〜22:00","closed":"**チャガルチ：毎月第1・第3火曜日が定休日**；南浦洞は年中無休","admission":"入場無料；**2階の刺し身（フェ）レストランのセットメニューは約30,000ウォン以上**（魚の種類により異なります）","walking":"平坦なショッピング街と市場フロアは歩きやすい；**2階の刺し身（フェ）レストラン**への短い階段の上り下りが必要"},"convenience":{"restroom":"BIFF広場とチャガルチ市場内に公衆トイレあり","parking":"ロッテ百貨店またはBIFF広場の公共駐車場をご利用ください；市場内に専用駐車場はありません"},"smartNotes":{"photo":"**カモメをモチーフにした現代建築（2006年リニューアルオープン、建築家：민현준〔ミン・ヒョンジュン〕）**、**1階の生け簀**、**BIFF広場のセレブ手形**（パク・チャヌク、ポン・ジュノなど）、**国際市場**（1,500店舗以上）。**露店商を撮影する際は必ず事前に許可を求めてください** — チャガルチのアジュンマ（おばちゃん）はカメラに対して遠慮なく物申すことで知られています。","tip":"**下で選んで上で食べる「フェ」スタイル**：1階で新鮮な魚介類を選び、2階のレストランでさばいてもらいます（チョコチュジャン＋焼酎がスタンダード）。**サンナクジ（活きタコの刺し切り）**は釜山の食文化を代表する一品——映画『オールド・ボーイ』（2003年）でも登場した料理です。"},"images":["/images/itinerary/jagalchi-harbor-sign.webp","/images/itinerary/jagalchi-market-interior.webp","/images/itinerary/jagalchi-night-building.webp","/images/tours/jagalchi-market/photo-001.webp","/images/tours/jagalchi-market/photo-002.webp","/images/tours/jagalchi-market/jagalchi-seafood-collage-ai.webp","/images/tours/jagalchi-market/photo-010.webp"]},{"number":8,"time":"≈ 17:30","duration":"30分","name":"釜山クルーズターミナルへ帰港","category":"帰港","description":"専用車が出発地点へ直接お送りします——大型クルーズ船の場合は**影島（ヨンド）東三洞（トンサムドン）の釜山港国際クルーズターミナル**、中型クルーズ船およびフェリーの場合は**草梁（チョリャン）の釜山港国際旅客ターミナル**——**乗船締め切り時刻の60〜90分前**に到着できるよう余裕を持ってスケジュールを組んでいます。ドライバーは午前中の出発地点と連携しており、日程中に変更があった場合（例：昼食が遅くなった場合）は配車センターに連絡してバッファ時間を調整します。\n\n到着ホールでのお降りとなり、クルーズ会社自身のギャングウェイシャトルが通常運行しています。","highlights":["出発ターミナル（東三洞または草梁）へ直接帰港","**乗船締め切りの60〜90分前に到着するよう余裕を確保**","日中のスケジュール変更が生じた場合はリアルタイムで配車調整"],"whyOnRoute":"途中停車なしの直行帰港により、乗船締め切りまでの余裕時間を確保します。30分あれば最悪の場合（ラッシュアワー）でも南浦洞からいずれかのターミナルまで移動できます；交通が空いていればさらに早着が可能です（ご希望の到着時間に合わせた送迎調整も承ります）。","_poi_meta":{"poi_key":"OPS_busan_cruise_return","kb_version":"1.15","verified_date":"2026-04-29"},"image":null}],"routeFlowStops":[{"type":"pickup","label":"クルーズ港"},{"type":"stop","label":"国連記念公園"},{"type":"stop","label":"太宗台（テジョンデ）"},{"type":"stop","label":"甘川（カムチョン）文化村"},{"type":"stop","label":"龍頭山（ヨンドゥサン）公園"},{"type":"stop","label":"チャガルチ市場"},{"type":"return","label":"クルーズ港"}],"routePhases":[{"phase":1,"title":"記憶と海","summary":"国連記念公園で静かな朝を過ごし、太宗台で東海の雄大な断崖絶壁へ。人混みを離れ、感慨深く景色豊かなひとときを。"},{"phase":2,"title":"色彩、高台、そして港","summary":"昼食後は甘川の彩り豊かな路地を散策し、龍頭山公園へ登って市街地のパノラマを望み、活気ある港のそばのチャガルチ市場で締めくくります。"},{"phase":3,"title":"時間通りの帰還","summary":"乗船締め切りの90分前をめどに、クルーズターミナルへ直行でお送りします。"}],"routeShapeIntro":{"title":"クルーズデーの流れ：記念公園 → 断崖絶壁 → 村 → 展望台 → 市場","body":"標準の5スポットコースはクルーズ旅客向けに設計されています：ゆったり歩ける静かなスタート（国連記念公園）、東海の絶景（太宗台）、色鮮やかな昼のハイライト（甘川）、市街地のパノラマ（龍頭山）、そして賑やかなグルメフィナーレ（チャガルチ）——最終スポットからクルーズターミナルまで車で10分。ご予約時に海東龍宮寺、スカイカプセル、梵魚寺などへの変更も完全カスタマイズ可能です。"},"whyTourWorks":{"bestFor":["8時間で釜山を最大限楽しみたいクルーズ旅客の方（時間通りの帰還を保証）","固定された団体ツアーよりも、プライベートでカスタマイズできる一日をご希望のカップル・ご家族","シニアを含む多世代グループ（プライベート車両なら乗り換え時の移動徒歩ゼロ）","団体ツアーのペースに縛られず、定番スポットを巡りたい釜山初訪問者","団体ツアーでは対応できない、移動・食事・ペースに関する特別なニーズをお持ちの旅行者"],"routeLogicSections":[{"title":"クルーズ寄港日にプライベートチャーターが選ばれる理由","icon":"anchor","items":[{"label":"時間通りの帰還がすべて","detail":"団体ツアーは固定スケジュールで動きますが、プライベートならお乗りの船の乗船締め切り時間を把握し、90分前に戻れるよう一日のスケジュールを調整します。"},{"label":"釜山は地理的に広がっています","detail":"クルーズ港から太宗台、甘川、チャガルチまでは橋や一方通行を経て約25kmあります。プライベート車両なら、団体ツアーが各スポットで費やす30〜45分の乗降ロスをカットできます。"},{"label":"再見積もり不要でカスタマイズ","detail":"チャガルチを海東龍宮寺に変更、展望台をスキップ、スカイカプセルを追加、または昼食を延長——料金は車両ごとの定額制で、変更のたびに追加料金は発生しません。"}]},{"title":"含まれるものと現地払いのもの","icon":"ticket","items":[{"label":"含まれるもの","detail":"プライベート車両、英語対応ドライバーガイド、高速料金・駐車料金すべて。クルーズターミナル／KTX駅／釜山市内ホテルへのお迎え込み。"},{"label":"現地払い","detail":"昼食（お一人様10,000〜20,000ウォン）、太宗台のダヌビトレイン（₩4,000）、釜山タワー展望台（₩12,000）、追加の場合はスカイカプセル。入場料はすべて手頃な価格で、当社からの隠れた追加料金は一切ありません。"},{"label":"追加オプション","detail":"金海空港への送迎は別途有料サービスとして対応可能。延長料金はドライバーへ1時間あたり現金30,000ウォン。"}]},{"title":"クルーズ専用の保証","icon":"shield-check","items":[{"label":"船が入港できない場合は全額返金","detail":"天候による船の欠航（台風・濃霧）の場合は全額返金いたします — 理由の確認や手数料は一切ございません。"},{"label":"ドライバーが乗船する船の出港時間を追跡します","detail":"お客様がご予約されたクルーズの具体的な日程に合わせて申し込みを行い、パンフレット記載の時刻ではなく実際の乗船締め切り時刻を基準に1日のスケジュールを組み立てます。"},{"label":"車のナンバープレートを事前にお知らせします","detail":"クルーズターミナルの到着ロビーでどの車を探せばよいか事前に把握できるため、出迎えの人々が集まる中でうろたえる必要はありません。"}]}],"sourcing":"ツアーの設計および運営内容は、AtoC Koreaが提供するプライベートチャータークルーズ寄港地ツアーの標準仕様に基づいています。対応クルーズ会社はロイヤル・カリビアン、プリンセス・クルーズ、MSC、コスタ、ダイヤモンド・プリンセス、そして釜山国際クルーズターミナルに入港するその他の主要オペレーターです。","lessIdealFor":["お一人様や予算重視の方 — プライベート料金は人数単位ではなく車両単位です","他のゲストと交流する団体ツアーの雰囲気を求める方","寄港時間が短く、8時間の終日上陸が難しいクルーズ乗客","ガイドと一緒に計画するより、固定の事前ルートを望む方"]},"practicalAccordionItems":[{"title":"乗降車・8時間のサービス枠について","icon":"map-pin","details":["乗車場所は、釜山クルーズターミナル到着ロビー、釜山駅（KTX）中央出口、または釜山市内中心部の主要ホテル（海雲台・西面・南浦洞・センタムシティ）よりお選びいただけます。","ドライバーはAtoC Koreaのサインを持ってお待ちしており、車のナンバープレートも事前にお知らせします。","降車場所はデフォルトでクルーズターミナル（全員乗船コール約90分前）となりますが、釜山市内中心部の主要ホテルへの送迎も可能です。","8時間のサービス枠は乗車時刻からカウントされます。超過分は1時間あたり30,000ウォンのキャッシュ払い（ドライバーへ直接）となり、対応可能かどうかは空き状況によります。","金海国際空港への送迎は別途有料オプションとなります（標準クルーズ寄港地ツアーの枠には含まれておりません）。"]},{"title":"料金に含まれるものと現地払いのもの","icon":"wallet","details":["含まれるもの：プライベート車両、英語対応ドライバーガイド、高速道路料金および駐車料金、燃料費。","現地払い：昼食（お一人様10,000〜20,000ウォン）、太宗台のダヌビ列車（オプション・往復₩4,000）、龍頭山の釜山タワー展望台（オプション・大人₩12,000）、代替プランとして海雲台のスカイカプセル（オプション・1カプセル40,000〜50,000ウォン）。","このデフォルトコースのすべての観光スポットは、上記のオプションを除き入場料無料です。"],"content":["含まれるもの: グループ専用車両とドライバー · 英語・中国語ガイド · クルーズターミナル往復送迎 · 通行料・駐車料・燃料費 · 予約手数料","含まれないもの: 全観光地の入場料 · 食事および飲み物 · 個人的な費用 · ガイド・ドライバーへのチップ · 旅行保険"],"preview":"含まれるもの: グループ専用車両とドライバー · 英語・中国語ガイド · クルーズターミナル往復送迎 · 通行料・駐車料・燃料費 · 予約手数料"},{"title":"カスタマイズとスポット変更について","icon":"sliders-horizontal","details":["デフォルトの5スポット・クルーズコース（国連記念公園 → 太宗台 → 甘川 → 龍頭山 → チャガルチ）は自由に変更可能です。","よくご要望いただる代替スポット：海東龍宮寺（港から東へ約40分の海辺の仏教寺院）、青沙浦・海雲台スカイカプセル、梵魚寺、松島スカイウォーク、五六島サンライズパーク。","ご希望のスポットをご予約時にお知らせいただければ、効率的な回り順をご提案します。8時間の枠内では4〜5か所の観光スポットをおすすめします。"]},{"title":"車両・ドライバー・乗車定員について","icon":"car","details":["エアコン完備のプライベート車両をご用意します。1〜3名様にはセダンまたはSUV、4〜7名様にはミドルサイズのバンをご用意します。","すべてのドライバーは有資格者で英語対応が可能です。ご予約時にお申し付けいただければ、中国語・日本語でのサポートも対応いたします。","車のナンバープレート、ドライバー名、連絡先電話番号は、ご到着前にメールまたはカカオトークでお知らせします。"]},{"title":"天候および船の欠航に関するポリシー","icon":"cloud-rain","details":["天候（台風・濃霧）の影響でクルーズ船が釜山に入港できない場合は全額返金いたします — 手数料や理由の確認は一切ございません。","当日晴天でスタートし途中から雨になった場合、ドライバーが屋内観光を優先できるようにコースを組み直します（釜山タワー、チャガルチ2階のレストラン、博物館への代替など）。","少なくとも2日前までのご連絡であれば、日程変更は手数料なしで承ります。"]},{"title":"使用言語とアクセシビリティ","icon":"users","details":["英語対応の有資格ドライバーガイドが標準となります。ご希望に応じて中国語または日本語対応のガイドもご用意できます。","車両は移動に制限のある旅行者に適しており、ドアツードアの送迎により乗り換え時の徒歩移動をほぼ省けます。","一部のスポットでは上り坂や階段の歩行が伴います（甘川、太宗台の灯台階段など）。ご予約時に移動に関するご要望をお知らせいただければ、行程を調整いたします。"]},{"id":"policy-surcharge-cancellation","title":"追加料金・キャンセル規定・ご利用条件","preview":"07:00より前の開始、または20:00より後の終了は1時間あたり50,000ウォン追加、釜山市外は130,000ウォン追加。24時間前まで無料キャンセル。4歳以上。クルーズ乗客限定。","content":["時間外追加料金: 07:00より前に開始する場合、または20:00より後に終わる場合、1時間あたり50,000ウォンが加算され、当日現地でお支払いいただきます。","釜山市外: 釜山市の境界を越える目的地は130,000ウォンが加算されます。","キャンセル規定: 開始の24時間前まで無料です。24時間を切ると返金されません。","最低年齢: 4歳以上の方がご利用いただけます。","クルーズ乗客限定: 釜山に寄港するクルーズでお越しの方にのみ販売しています。釜山寄港のないご予約はお断りのうえ返金いたします。","帰着時刻: 一日の行程は船の乗船締切時刻を基準に組まれ、降車はそれより前に配置されます。"]}],"practicalWeatherStatic":{"summary":"釜山は四季がはっきりした湿潤亜熱帯気候です。クルーズシーズンは春（3〜5月）と秋（9〜11月）に集中しており、いずれも12〜25°Cで降雨量が少なく快適です。夏（6〜8月）は蒸し暑く、梅雨の時期にスコールが降ることもあります。冬（12〜2月）は涼しく風が強い季節です。","advice":"春・秋は重ね着を、夏は日焼け止めと軽い雨具を、冬は太宗台の海岸断崖に備えて暖かいコートと手袋をご用意ください。"},"seasonalVariations":[{"season":"春（3〜5月）","summary":"ダルマジの丘、龍頭山公園、光安里ビーチでは3月下旬〜4月上旬が桜の見頃です。12〜22°Cで快適。薄手の重ね着がおすすめです。","swaps":"桜の見頃の週には、太宗台と甘川の間にダルマジの丘の桜ドライブを追加できます。"},{"season":"夏（6〜8月）","summary":"蒸し暑く25〜32°C、6〜7月は梅雨のにわか雨が降ることも。日没が遅いため、1日の終わりに海岸スポットを追加するのもおすすめです。","swaps":"タワーの展望台の代わりに海雲台スカイカプセル（屋根付き・冷房完備）を選ぶか、潮風を楽しめる松島スカイウォークを追加するのもよいでしょう。"},{"season":"秋（9〜11月）","summary":"韓国で最も旅行に適した気候。15〜25°C、低湿度、黄金色の光。クルーズシーズンのピークです。","swaps":"秋はすべての定番スポットが映えます。紅葉を楽しむなら梵魚寺の追加もご検討ください。"},{"season":"冬（12〜2月）","summary":"涼しく風が強く0〜10°Cですが、クルーズ運航は続きます。海岸のスポットは冬ならではの荒涼とした美しさがあります。","swaps":"太宗台の灯台階段での屋外滞在は短めに。屋内2階レストランで温かいスープが楽しめるチャガルチ市場での滞在時間を長めに取るのがおすすめです。"}],"bookingTrustItems":[{"icon":"shield-check","title":"船が接岸できない場合は全額返金","detail":"天候による運航キャンセルの場合は全額返金。手数料なし、理由確認なし。"},{"icon":"clock","title":"定刻帰着保証","detail":"お客様が乗船される船の出港時間を把握し、90分の余裕を持って帰着できるよう1日の行程を管理します。"},{"icon":"user-check","title":"有資格の地元ドライバーガイド","detail":"ドライバーは全員、専門資格を持ち英語対応可能で、AtoC Koreaの釜山パートナーネットワークにより認定されています。"}],"bookingSupportSteps":[{"step":1,"title":"オンライン予約","detail":"日程を選ぶだけで今日のお支払いは不要。今すぐ予約して、後払いOK。"},{"step":2,"title":"クルーズの詳細をお送りください","detail":"船名・到着日・停泊岸壁をお知らせください。24時間以内にスケジュールを確認してご連絡します。"},{"step":3,"title":"立ち寄りスポットのカスタマイズ（任意）","detail":"ご希望の追加または省略スポットを、ツアーの2日前までにお送りください。"},{"step":4,"title":"ドライバー情報のお知らせ","detail":"車両のナンバープレート、ドライバー名、連絡先電話番号を前日にお送りします。"},{"step":5,"title":"クルーズターミナルにてお出迎え","detail":"下船後30分以内に、AtoC Koreaのサインを持ったドライバーが到着ホールにてお待ちします。"},{"step":6,"title":"船への時間通りの帰還","detail":"全員乗船コールの約90分前にお送りします。ホテルまたはKTX駅への送迎への変更も可能です。"}],"staticQuestions":[{"question":"プライベート車両は何名まで乗車できますか？","answer":"1〜3名様はセダンまたはSUV、4〜7名様はミッドサイズバンをご利用いただけます。それ以上の大人数の場合は、専用お見積もりのためお問い合わせください。"},{"question":"クルーズ船が遅延した場合や入港できない場合はどうなりますか？","answer":"天候不良により船が釜山に入港できない場合は、手数料・理由を問わず全額返金いたします。単純な遅延の場合は、ドライバーが待機してスケジュールを調整し、8時間のご利用時間は実際のピックアップ時刻からスタートします。"},{"question":"立ち寄りスポットはカスタマイズできますか？","answer":"はい、完全にカスタマイズ可能です。ご予約時に希望のスポットをお知らせいただければ、最適な順序でご案内します。デフォルトの5か所巡りのクルーズ旅程はあくまで出発点であり、固定プランではありません。よくある変更先には、海東龍宮寺・スカイカプセル・梵魚寺などがあります。"},{"question":"金海空港での送迎は含まれていますか？","answer":"いいえ。金海空港の送迎は別途有料オプションです（標準のクルーズ寄港観光には含まれません）。空港が都市圏の西端に位置しているためです。ご予約時にリクエストいただければ、追加料金をご案内します。"}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"日付と人数を選択すると、リアルタイムの空き状況を確認して予約を完了できます。","price":{"amountLabel":"456.99","currency":"USD","per":"vehicle","salePriceUsd":456.99}},"pickup_dropoff":{"type":"multi_point_pickup","meeting_points":[{"name":"釜山クルーズターミナル（国際クルーズ港）","time":"Within 30 min of cruise disembarkation","note":"釜山に寄港するクルーズ船は、どちらのターミナルにも着岸します。どちらになるかは船の着岸場所によって決まり、ご予約後に確定します。到着ホールでガイドがお待ちしています。"},{"name":"釜山駅（KTX）中央出口","time":"Flexible — confirm at booking","note":"釜山に寄港するクルーズ船は、どちらのターミナルにも着岸します。どちらになるかは船の着岸場所によって決まり、ご予約後に確定します。到着ホールでガイドがお待ちしています。"},{"name":"釜山中心部の任意のホテル","time":"Flexible — confirm at booking","note":"釜山に寄港するクルーズ船は、どちらのターミナルにも着岸します。どちらになるかは船の着岸場所によって決まり、ご予約後に確定します。到着ホールでガイドがお待ちしています。"}],"dropoff_points":[{"name":"釜山クルーズターミナル（船へのお戻り）","approx_time":"全員乗船コールの約90分前","note":"釜山に寄港するクルーズ船は、どちらのターミナルにも着岸します。どちらになるかは船の着岸場所によって決まり、ご予約後に確定します。到着ホールでガイドがお待ちしています。"},{"name":"釜山中心部の任意のホテル","approx_time":"サービス終了時刻ごろ","note":"釜山に寄港するクルーズ船は、どちらのターミナルにも着岸します。どちらになるかは船の着岸場所によって決まり、ご予約後に確定します。到着ホールでガイドがお待ちしています。"}],"hotel_pickup_available":true,"notes":"8時間のサービス時間はピックアップ時刻からスタートします。金海国際空港の送迎は別途有料オプションとして対応可能です（標準のクルーズ寄港観光には含まれません）。超過料金は1時間あたり30,000ウォンで、ドライバーへの現金払いとなります（ドライバーの空き状況による）。日程変更のリクエストは、元の予約日の少なくとも2日前までにお申し出ください。ただし天候による船のキャンセルの場合は全額返金が適用されます。"},"matching_profile":{"profile_version":6,"is_active":true,"product_id":"busan-private-car-charter-cruise-shore","product_type":"private","route_type":"customizable","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"private_vehicle","duration_hours":8,"region_tags":["busan","busan_central","busan_eastern","cruise_port"],"theme_tags":["cruise_shore_excursion","private_charter","city_highlights","coastal","cultural","memorial"],"poi_tags":["un_memorial_c