UPDATE public.tour_product_pages SET
  title = '釜山邮轮岸上私人包车',
  subtitle = '由持牌英语司机导游陪同，乘坐空调私家车，自由规划您的釜山专属一日行程——保证准时返回船上。',
  region_label = '釜山（邮轮港 + 市区）',
  duration_label = '8小时',
  stops_count = 5,
  badges = ARRAY['私人游', '可定制路线', '含邮轮码头接送']::text[],
  hero_image_url = '/images/tours/taejongdae/chatgpt-image-2026-5-10-12-26-45.webp',
