d_for":["solo_budget","value_seekers","mobility_severely_limited"],"anchor_pois":["UN Memorial Cemetery","Taejongdae","Gamcheon Culture Village","Yongdusan Park & Busan Diamond Tower","Jagalchi Market"],"anchor_poi_keys":["un_memorial_cemetery","taejongdae","gamcheon_culture_village","yongdusan_park","jagalchi_market"],"enrichment_batch":"17b","enrichment_date":"2026-04-29","enrichment_kb_version":"1.24","enrichment_target_kb_version":"1.25","profile_version_pre":6,"profile_version_post":6,"schema_version":7,"patch_type":"polish_existing_pv6_to_a_grade","patch_target":"15 substantive stops across 3 tours; Batch 13a/13b authoring → A-grade pv=6 PASS"},"page_sections":[{"id":"hero","section_html_id":null,"component":"TourHeroSection","props":{"headlineLine1":"釜山邮轮岸上私人包车","headlineLine2":"一日游","hero":{"imageUrl":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","imagePosition":"center 45%","tagline":"从城山日出峰到挟才海滩，再到天地渊瀑布——九小时私人专属时光，您的路线，您的节奏，配备持证司导一体司机。","pills":["私家车","持牌司机兼导游","东线 / 西线 / 南线"],"meta":{"duration":"9小时","region":"济州全岛","stops":"定制","rating":0,"ratingStars":0}}}},{"id":"subnav","section_html_id":null,"component":"TourTabsNav *(UI组件名，建议保留原文)*","props":{"subnavItems":[{"id":"overview","label":"概览"},{"id":"itinerary","label":"行程"},{"id":"details","label":"详情"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"评价"}]}},{"id":"overview","section_html_id":"overview","component":"TourAtAGlance *(UI组件名，建议保留原文)*","props":{"glanceItems":[{"icon":"car","label":"游览方式","value":"私人包车"},{"icon":"map","label":"路线规划","value":"完全可定制"},{"icon":"user-check","label":"导游","value":"持牌司机兼导游"},{"icon":"clock","label":"时长","value":"9小时"},{"icon":"ticket","label":"门票费用","value":"现场自付"},{"icon":"utensils-crossed","label":"午餐","value":"现场自付"}]}},{"id":"atmosphere","section_html_id":null,"component":"TourAtmosphereGallery *(UI组件名，建议保留原文)*","props":{"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","alt":"在韩联合国纪念公园 — 图库图片","caption":"在韩联合国纪念公园","location":"在韩联合国纪念公园","atmosphere":"济州最具代表性的联合国教科文组织世界遗产，东线必游胜地"}]}},{"id":"itinerary","section_html_id":"itinerary","component":"TourTimelineSection","props":{"itineraryStops":[{"number":1,"time":"Flexible","duration":"自定义","name":"东线：世界遗产与韩剧海岸","category":"城山、牛岛、万丈窟、涉地可支","description":"地标最密集的路线选项，涵盖济州岛最具代表性的世界遗产与韩剧胜地。常规停靠点包括城山日出峰（世界遗产日出峰）、牛岛（乘渡轮可达的海岛，沿岸设有海滩）、万丈窟熔岩洞穴（世界遗产洞穴）、涉地可支（因韩剧而闻名的海岸海角）、城邑民俗村以及咸德海滩。","image":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","highlights":["城山日出峰：世界自然遗产，济州岛标志性日出景点","牛岛：乘渡轮可达的岛屿，拥有白沙滩与灯塔美景","万丈窟：世界上最长的熔岩洞穴之一（世界遗产）","涉地可支与城邑：经典韩剧取景地与民俗村氛围"],"timeUsed":["酒店接送并前往东海岸","2至3个主要地标停靠（司机兼导游根据团队节奏灵活调整）","午餐休息（自由选择；通常在城山附近或东海岸）","可选牛岛渡轮摆渡（需额外费用；车辆可停放或随船运输）"],"whyOnRoute":"这是首次造访济州岛、希望游览最多知名地标的游客的最佳路线：城山日出峰是全岛被拍摄次数最多的单一地标，而万丈窟则为此路线增添了独特的世界遗产地下探险体验。","visitBasics":{"hours":"大多数景点开放时间为09:00至18:00；万丈窟每月第一个星期三闭馆","closed":"城山每月第一个周一休息；万丈窟每月第一个周三休息","admission":"现场直接付款：城山 5,000韩元，万丈窟 4,000韩元，涉地可支 4,000韩元，牛岛渡轮往返最低 10,500韩元","walking":"中等至较高难度（城山顶峰攀登是全程最费体力的部分）"},"convenience":{"restroom":"各主要景点均有提供","parking":"司机兼导游负责所有停车事宜"},"smartNotes":{"photo":"晴天早晨拍摄城山顶峰是全程最佳单张拍摄时机；涉地可支在午后侧光下效果更佳。","facilities":"城山和咸德海滩是最优质的餐饮聚集地；东线的餐饮选择密度高于西线。","tip":"城山顶峰攀登是老年人或行动不便旅客的体力瓶颈，在山脚区域观景同样可行。"},"_poi_meta":{"poi_key":"route_variant_east","verified":false,"match":"route_variant_no_single_poi","note":"Route option for private charter — represents a multi-POI bundle (Seongsan, Udo, Manjanggul, Seopjikoji); not a single matchable POI"}},{"number":2,"time":"Flexible","duration":"定制","name":"西线：海滩、茶园与咖啡海岸","category":"协才，翰林公园，O''sulloc茶博物馆，涯月","description":"全程最上镜且节奏最悠闲的路线。主要景点包括：协才海滩（济州最具代表性的翡翠色海滩）、翰林公园（亚热带花园与熔岩洞穴）、O''sulloc茶博物馆（茶田与咖啡馆）及涯月咖啡街（日落海岸咖啡文化）。特别适合情侣和摄影爱好者。","image":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","highlights":["协才海滩：翡翠色海水、白色沙滩，可眺望飞扬岛","翰林公园：亚热带园林，园内设有两处熔岩洞穴","O''sulloc：济州最负盛名的茶博物馆，室内设施完善","涯月咖啡街：日落海岸线与济州当代咖啡文化"],"timeUsed":["酒店接送，前往西海岸","上午游览海滩与园林景点","午餐休息（自由选择；翰林或协才附近餐厅选择最为丰富）","下午游览茶博物馆与涯月，结束当天行程"],"whyOnRoute":"这是最适合情侣、摄影爱好者及喜欢悠闲节奏旅客的路线。涯月尤其适合作为日落收尾，O''sulloc则为行程提供了一处出色的室内缓冲区，可应对天气变化。","visitBasics":{"hours":"大多数景点营业时间为09:00至18:00；涯月咖啡馆营业时间不一","closed":"大多数景点全年开放","admission":"现场直接付款：翰林公园 15,000韩元，O''sulloc免费入场（特别项目另收费），海滩免费","walking":"轻松至中等难度"},"convenience":{"restroom":"各主要景点均有提供","parking":"司机兼导游负责所有停车事宜"},"smartNotes":{"photo":"协才海滩在上午晚些时候的阳光下翡翠色海水最为迷人；涯月在日落时分拍摄效果最佳。","facilities":"O''sulloc是西线所有景点中室内设施最完善的；涯月的咖啡馆和小吃选择最为集中丰富。","tip":"若当天天气预报不确定，西线比东线更能应对小雨天气。"},"_poi_meta":{"poi_key":"route_variant_west","verified":false,"match":"route_variant_no_single_poi","note":"Route option for private charter — multi-POI bundle (Hyeopjae, Hallim, O''sulloc, Aewol)"}},{"number":3,"time":"Flexible","duration":"自定义","name":"南部路线：瀑布与火山海岸","category":"天地渊、柱状节理带、山房山、偶来市场","description":"风景最为壮观的路线。典型游览点包括天地渊瀑布（森林瀑布）、柱状节理带悬崖（玄武岩柱海岸）、药泉寺（东亚最大寺庙之一）、山房山（火山穹丘，可俯瞰海景）、正房瀑布（亚洲少数直接注入大海的瀑布之一）及西归浦偶来市场。","image":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","highlights":["天地渊瀑布：西归浦经典森林瀑布","柱状节理带悬崖：南部海岸的六角形玄武岩柱","山房山：火山穹丘，可欣赏海崖寺庙景观","偶来市场：西归浦最热闹的传统市场，汇聚各类小吃与纪念品"],"timeUsed":["酒店接送，前往南部海岸","上午游览瀑布与玄武岩悬崖","在西归浦享用午餐（自由选择）","下午游览山地或寺庙，市场参观收尾"],"whyOnRoute":"对于希望体验地质多样性的旅行者而言，这是最佳路线：一天之内游览寺庙、瀑布、玄武岩悬崖、火山穹丘和市场，充分领略济州\"火山岛\"的独特魅力。","visitBasics":{"hours":"大多数景点开放时间为09:00至17:30","closed":"大多数景点全年开放","admission":"现场付款：天地渊 2,500韩元，柱状节理带 2,000韩元，正房瀑布 2,000韩元，药泉寺免费，山房山 1,000韩元","walking":"中等强度（天地渊和山房山步行量最大）"},"convenience":{"restroom":"各主要景点均有提供","parking":"司机兼导游负责所有停车事宜"},"smartNotes":{"photo":"柱状节理带在下午侧光下效果最佳；偶来市场在傍晚夜市区开放时最为热闹。","facilities":"偶来市场是最佳美食聚集地；药泉寺提供最宁静的室内参观体验。","tip":"天地渊和山房山均需攀爬台阶。膝盖不适的旅行者建议二选一，不必两处都去。"},"_poi_meta":{"poi_key":"route_variant_south","verified":false,"match":"route_variant_no_single_poi","note":"Route option for private charter — multi-POI bundle (Cheonjiyeon, Jusangjeolli, Yakcheonsa, Sanbangsan, Jeongbang)"}},{"number":4,"time":"Flexible","duration":"自定义","name":"自定义路线：打造专属一日行程","category":"发送您的专属行程","description":"除三条推荐路线外，您还可以自由组合景点或发送专属行程。可选景点包括：济州海洋水族馆、ECO乐园主题公园、山君不离火山口、咸德海滩、茶花山丘、泰迪熊野生动物园、西归浦潜水艇（文森岛水下游览）、海豚游艇观光、松岳山、悬崖咖啡厅及乱打秀。","image":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","highlights":["如时间允许，可将东海岸联合国教科文组织遗址与西海岸茶园相结合","在任意路线中加入海女（女潜水员）海鲜午餐体验","将海滩上午游与山地或寺庙下午游相结合","搭配您最喜爱韩剧的取景地探访"],"timeUsed":["在接送时或之前与您的司机导游讨论行程计划","司机导游根据交通状况和渡轮时刻灵活调整行程节奏","在9小时行程窗口内返回您的酒店"],"whyOnRoute":"这是四个选项中最灵活的一种。最适合再次游览济州的游客、有特定兴趣爱好的旅行者（追韩剧取景地、摄影、美食），以及希望量身定制行程的家庭。","visitBasics":{"hours":"取决于所选景点","closed":"取决于所选景点","admission":"所有景点门票费用均现场自付","walking":"取决于所选景点"},"convenience":{"restroom":"司机导游将根据各景点的配套设施安排行程","parking":"司机导游负责处理所有停车事宜"},"smartNotes":{"photo":"定制路线可专门针对特定季节的最佳拍摄时机：春季的油菜花田、初夏的绣球花、秋季的粉黛乱子草。","facilities":"出发前请与您的司机导游协商用餐时间和中途休息站安排。","tip":"请在出行前几天发送您的行程草案，以便司机导游提前排查任何时间或通行方面的问题，尤其是渡轮时刻表相关事宜。"},"_poi_meta":{"poi_key":"route_variant_custom","verified":false,"match":"route_variant_no_single_poi","note":"Custom route — fully guest-defined; no fixed POI set"}}]}},{"id":"day_flow","section_html_id":null,"component":"TourDayFlowSection","props":{"routeFlowStops":[{"id":"01","name":"酒店接送","theme":"开始"},{"id":"02","name":"选择路线","theme":"东部 / 西部 / 南部"},{"id":"03","name":"午餐休息","theme":"重置"},{"id":"04","name":"下午游览","theme":"继续"},{"id":"05","name":"酒店送达","theme":"结束"}],"routePhases":[{"label":"出发","range":"1","theme":"济州酒店接送","bgClass":"bg-sky-50/70","textClass":"text-sky-700","dotClass":"bg-sky-500"},{"label":"出行日","range":"2-4 > **注：** 第14项（`TourDayFlowSection`）和第28项（`bg-sky-50/70`）为技术性代码标识符/CSS类名，保留原文不作翻译。","theme":"选择您的路线","bgClass":"bg-emerald-50/70","textClass":"text-emerald-700","dotClass":"bg-emerald-500"},{"label":"完成","range":"5","theme":"返回酒店","bgClass":"bg-amber-50/70","textClass":"text-amber-700","dotClass":"bg-amber-500"}],"routeShapeIntro":{"title":"私人包车一日游行程安排","subtitle":"08:00至09:00在您的济州酒店接送，随后开启灵活自由的9小时游览——东线、西线、南线任选，或按您的定制计划进行。司机兼导游将根据天气和路况调整行程节奏，约17:00至18:00返回送达。"}}},{"id":"details","section_html_id":"details","component":"TourFitSection","props":{"whyTourWorks":{"bestFor":["携带儿童（含幼小孩子）的家庭","包含老年人的多代同堂团体","希望享受轻松韩剧风情一日游的情侣与蜜月旅行者","希望定制专属路线的再次到访济州的游客","追拍特定季节风光的摄影师（油菜花、绣球花、粉黛乱子草）"],"routeLogicSections":[{"title":"为何在济州选择私人包车更胜一筹","icon":"car","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"济州岛确实幅员辽阔","detail":"该岛东西横跨约73公里。团体巴士游在每个景点浪费大量等待时间；私人包车则彻底省去这些耗时环节。"},{"label":"天气瞬息万变","detail":"济州小气候每小时都可能发生变化。司机兼导游可随时将户外景点替换为室内景点（涵林公园溶洞、O''sulloc茶博物馆、药泉寺），确保行程不受影响。"},{"label":"门到门的舒适体验","detail":"酒店直接接送，无需乘坐机场区域的接驳巴士，无需承受深夜末班车的压力，也无需拖着行李在中转站之间步行奔波。"}]},{"title":"如何在东线、西线与南线之间做出选择","icon":"map","iconBg":"bg-amber-50/80","iconColor":"text-amber-600","items":[{"label":"东线：初次到访、打卡地标的首选","detail":"城山日出峰与万丈窟是济州最具代表性的两处世界自然遗产；东线路线带来最大的地标认知价值。"},{"label":"西线：悠闲赏景、尽情拍照","detail":"协재海滩、涵林公园、O''sulloc茶博物馆与涯月共同构成一段节奏舒缓、更适合情侣的一日游，拍照收获颇丰，并以绝美日落收尾。"},{"label":"南线：感受震撼人心的地质奇观","detail":"瀑布、玄武岩悬崖、火山穹丘与古寺，一日之内一览无余，赋予这条路线济州最鲜明的\"火山岛\"传奇色彩。"}]},{"title":"当天可能发生的变化","icon":"clock-3","iconBg":"bg-slate-50/80","iconColor":"text-slate-698","items":[{"label":"天气调整","detail":"小雨通常不影响行程路线；强风通常会缩短沿海景点的停留时间（城山、柱状节理、涯月）。"},{"label":"东线路线的牛岛渡轮","detail":"前往牛岛需要乘坐单独的渡轮。车辆可随船托运（需额外费用）或停放在码头。渡轮时刻会影响全天的行程节奏。"},{"label":"可申请延时服务","detail":"如需超过9小时，每延长1小时须额外向司机支付25,000韩元现金，具体视司机档期而定。"}]}],"lessIdealFor":["独自出行的经济型旅客（私人包车价格按车辆计算）","希望与其他旅客同行、享受社交体验的旅客","需要全程专业讲解、持证正式导游服务的旅客（司机兼导游持有执照，但讲解深度不及正式导游级别）","希望行程含所有门票及餐食的旅客"]}}},{"id":"practical","section_html_id":null,"component":"TourPracticalDetails","props":{"practicalAccordionItems":[{"id":"pickup","title":"接送服务","preview":"济州岛全岛酒店均可接送；请提前10分钟在大堂等候","content":["济州岛全岛任意地点均包含酒店接送服务（济州市、西归浦、中文等）","接送时间通常安排在08:00至09:00之间","请在约定出发时间前10分钟于酒店大堂等候","返程可送至您在济州岛的酒店或您指定的任意地点（如晚餐餐厅或机场）","返回时间通常在9小时服务窗口内的17:00至18:00之间","如需更改行程，请至少在原预订日期前2天联系运营商"]},{"id":"vehicle","title":"车辆与团队规模","preview":"根据团队人数和行李量分配车辆","content":["车辆类型根据乘客人数和行李件数精确匹配","预订时请填写准确的乘客人数和行李件数","常用车辆包括：1至3人乘坐轿车、4至5人乘坐中型SUV、6至9人乘坐Staria或Carnival厢式车","人数较多的团队可能分配多辆车或另行报价"]},{"id":"duration","title":"9小时服务窗口及延时说明","preview":"从接送时起严格执行9小时服务窗口","content":["9小时服务窗口从酒店接送时间开始计算","超时费用为每小时25,000韩元，须以现金直接支付给司机","超时服务须视司机是否有空及适用的服务时数规定而定","牛岛渡轮往返时间计入9小时行程内，除非另有约定"]},{"id":"extras","title":"您需要了解的额外费用","preview":"牛岛渡轮、门票及餐饮费用","content":["牛岛汽车渡轮：额外收费（依车辆大小而异）；步行旅客渡轮约10,500韩元起（每人往返）","所有门票费用须在各景点现场直接支付","餐饮费用自付；司导可推荐当地特色美食（黑猪肉、肉丝面、鲍鱼粥）","可自愿给予司机小费，不作强制要求"]},{"id":"weather","title":"天气政策","preview":"私人包车形式能灵活应对济州岛多变的天气状况","content":["小雨：大多数景点照常开放；司导可调整行程转往室内景点","强风：城山、柱状节理带及涯月的海岸游览时间可能缩短","台风预警日：运营商将联系您安排改期","汉拿山降雪可能导致1100高地道路封闭；司导将以其他内陆景点代替"]},{"id":"included","title":"费用包含","preview":"车辆及持牌司导；门票及餐饮须自行支付","variant":"包含项目","content":["专属车辆（根据团体人数提供轿车、SUV或面包车）","持牌英语司导","济州岛任意地点酒店接送","标准路线的燃油费及过路费","所有门票费用不含在内，须在各景点现场直接支付","餐饮费用不含在内","个人购物不含在内","司机小费不含在内"]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"实时天气整合"},"tomorrow":{"temp":"—","label":"每日更新"}},"seasonalVariations":[{"name":"春季","icon":"flower","description":"三月下旬至四月，油菜花铺满东海岸；四月初樱花盛放。气温温和，晴空万里，是最均衡宜人的季节。","tag":"油菜花季","bgClass":"bg-spring","iconColor":"text-pink-500"},{"name":"夏季","icon":"sun","description":"海滩旺季，协才与咸德海水浴场最为迷人；六月绣球花为西海岸增添色彩。八月湿度较高，需留意台风天气。","tag":"海滩季节","bgClass":"bg-summer","iconColor":"text-yellow-500"},{"name":"秋季","icon":"leaf","description":"粉黛乱子草花田于十月中旬至十一月初达到全盛；汉拿山与城山的能见度最佳。通常是济州岛最适合摄影的季节。","tag":"最佳摄影季节","bgClass":"bg-autumn","iconColor":"text-orange-500"},{"name":"冬季","icon":"snowflake","description":"山茶花丘从十二月至二月持续盛开；汉拿山山顶可见积雪覆盖。天气寒冷但景色迷人，各大景点人流稀少。","tag":"山茶花与雪景","bgClass":"bg-winter","iconColor":"text-sky-500"}]}},{"id":"booking_support","section_html_id":null,"component":"TourBookingSupportSection","props":{"bookingTrustItems":[{"icon":"check-circle","title":"持牌本地运营商","description":"持有全额保险的韩国授权旅游运营商","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600"},{"icon":"route","title":"路线专家","description":"精心定制的行程，绝非千篇一律的套路线路","iconBg":"bg-sky-50/80","iconColor":"text-sky-600"},{"icon":"users","title":"精选团队规模","description":"依据路线合理配置人数","iconBg":"bg-amber-50/80","iconColor":"text-amber-600"}],"bookingSupportSteps":[{"timing":"即时","title":"即时确认","detail":"含行程摘要的预订确认通知"},{"timing":"出发前12小时","title":"12小时提醒","detail":"天气更新及路线调整"},{"timing":"前一天晚上","title":"最终接送信息","detail":"确切接送时间及司机联系方式"},{"timing":"游览当天早晨","title":"当日路线说明","detail":"根据实时状况的早间简报"},{"timing":"游览途中","title":"逐站小贴士","detail":"每个景点的实时指引"},{"timing":"游览结束后","title":"游览后支持","detail":"后续跟进与推荐"}]}},{"id":"faq","section_html_id":"faq","component":"TourFaqSection","props":{"staticQuestions":[{"id":"first-time","question":"对于初次游览济州岛（东部、西部或南部）的游客，这是个好选择吗？","answer":"是的——一天的均衡行程中涵盖了该地区最具特色的景点。"},{"id":"walking","question":"步行难度大吗？","answer":"步行难度适中，部分路段较为活跃。"},{"id":"family","question":"这个游览适合家庭参加吗？","answer":"是的——大多数家庭都能舒适参与。"},{"id":"seniors","question":"老年人可以舒适地参加吗？","answer":"是的——行程节奏和步行量对活跃的老年人来说都很舒适。"}]}},{"id":"reviews","section_html_id":"reviews","component":"TourReviewsSection","props":{"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]}}},{"id":"sticky_booking","section_html_id":null,"component":"TourStickyBookingBar","props":{"note":"选择日期与人数，即可查看实时可订状态并完成预订。","price":{"amountLabel":"","currency":"USD","per":"vehicle"}}}],"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","last_modified":"2026-04-28","version_history":["v15.4_new_tour_creation"],"fix_passes":{"v15.4_new_tour_creation":"Created new tour from GYG product ID t899592 (Busan private car charter for cruise shore). Structural template: jeju-island-private-car-charter-tour. Content template: busan-small-group-sightseeing-tour-cruise-passengers. POI operational data (visitBasics/convenience/smartNotes) sourced from poi_knowledge_base.json (centralized KB built in Step 2). REASONABLE-ASSUMPTION FIELDS that may need patching once the live GYG