UPDATE public.tour_product_pages SET
  title = '釜山郵輪岸上私人包車',
  subtitle = '由持牌英語司機導遊陪同，乘坐冷氣私人車輛，自由規劃您的釜山一日行程——保證準時返回郵輪。',
  region_label = '釜山（郵輪碼頭＋市區）',
